CURRENT_OS = platform.system().lower()

GREEN = "\033[92m"
RESET = "\033[0m"


def _early_reset_console_color() -> None:
    try:
        print(RESET, end="", flush=True)
    except Exception:
        pass


def _creator_uncaught_exception(exc_type, exc_value, _traceback) -> None:
    """Map unexpected creator/startup failures to the documented exit contract."""
    if issubclass(exc_type, KeyboardInterrupt):
        print("\nOperation cancelled by user.", file=sys.stderr)
        print(RESET, end="", flush=True)
        raise SystemExit(130)
    print(f"\nERROR: {exc_value}", file=sys.stderr)
    print("Creator terminated due to a fatal error.", file=sys.stderr)
    print(RESET, end="", flush=True)
    raise SystemExit(2)


# Register the reset before enabling color or enforcing the minimum Python
# version so even an unsupported-runtime rejection restores the terminal.
atexit.register(_early_reset_console_color)
sys.excepthook = _creator_uncaught_exception
print(GREEN, end="")

