if CURRENT_OS == "windows":
    os.system(
        f"title Topaz Offline Download Creator v{VERSION} Build {BUILD}"
    )

TRACEBACK_TEXT_ART_BASE64 = (
    ''
)

_ORIGINAL_TRACEBACK_PRINT_EXCEPTION = traceback.print_exception
_BUG_PRINTING = False

def BUG() -> None:
    global _BUG_PRINTING
    if _BUG_PRINTING:
        return
    _BUG_PRINTING = True
    try:
        decoded = base64.b64decode(TRACEBACK_TEXT_ART_BASE64).decode("utf-8")
        print()
        print(decoded, flush=True)
        print(flush=True)
    except Exception:
        pass
    finally:
        _BUG_PRINTING = False

def _restore_console_color() -> None:
    try:
        print(GREEN, end="", flush=True)
    except Exception:
        pass


def _reset_console_color() -> None:
    try:
        print(RESET, end="", flush=True)
    except Exception:
        pass


def _stick_bug_print_exception(*args, **kwargs) -> None:
    BUG()
    try:
        _ORIGINAL_TRACEBACK_PRINT_EXCEPTION(*args, **kwargs)
    finally:
        _restore_console_color()

def clean_exception_handler(exception_type, exception_value, exception_traceback) -> None:
    try:
        if issubclass(exception_type, KeyboardInterrupt):
            print()
            print("=" * 60)
            print("Operation cancelled by user.")
            print("=" * 60)
            raise SystemExit(130)
        print(f"\nERROR: {exception_value}", file=sys.stderr)
        print("Creator terminated due to a fatal error.", file=sys.stderr)
        raise SystemExit(2)
    finally:
        _reset_console_color()

def thread_exception_handler(args) -> None:
    if args.exc_type is KeyboardInterrupt:
        return
    traceback.print_exception(args.exc_type, args.exc_value, args.exc_traceback)

def unraisable_exception_handler(args) -> None:
    traceback.print_exception(type(args.exc_value), args.exc_value, args.exc_traceback)

traceback.print_exception = _stick_bug_print_exception
sys.excepthook = clean_exception_handler
threading.excepthook = thread_exception_handler
sys.unraisablehook = unraisable_exception_handler

