# Detailed runtime self-tests run only when explicitly enabled. Essential
# compilation, inventory, manifest, and launcher-structure checks still run
# during every creator execution.
SHOW_DEVELOPER_VALIDATION = False
DEBUG_CERTIFICATE = False
SELF_TEST_MODE = False

DEVELOPER_VALIDATION_RESULTS: list[tuple[str, str]] = []


def record_developer_check(
    label: str,
    status: str = "PASSED",
) -> None:
    DEVELOPER_VALIDATION_RESULTS.append((label, status))


VISIBLE_SECTION_TOTAL = 3 if SHOW_DEVELOPER_VALIDATION else 2

