def portable_display_path(path: Path | str) -> str:
    """Return a short display path relative to the creator location."""
    candidate = Path(path).resolve()

    try:
        relative = candidate.relative_to(PROJECT_ROOT)
    except ValueError:
        return str(candidate)

    if relative == Path("."):
        return "~"

    if CURRENT_OS == "windows":
        return "~\\" + str(relative).replace("/", "\\")

    return "~/" + relative.as_posix()


def portable_display_alias(*parts: str) -> str:
    """Return a display-only alias without changing the real file path."""
    cleaned_parts = [str(part).strip("/\\") for part in parts if str(part)]

    if not cleaned_parts:
        return "~"

    if CURRENT_OS == "windows":
        return "~\\" + "\\".join(cleaned_parts)

    return "~/" + "/".join(cleaned_parts)

