# Extra-package inventories are read from the embedded V2 JSON rather than
# selected through version constants. The V2 records remain the authoritative
# integrity inventory. Captured URLs that are not representable in strict V2
# are retained separately so historical requests are never discarded merely
# because an upstream object was replaced or unavailable when verified.
VIDEO_AI_715_V2_MANIFEST_NAME = "VIDEO_AI_7.1.5_EXTRA_PACKAGES.v2.json"
VIDEO_161_EXTRA_V2_MANIFEST_NAME = "VIDEO_1.6.1_EXTRA_PACKAGES.v2.json"
STARLIGHT_25_V2_MANIFEST_NAME = "STARLIGHT_2.5.v2.json"


def embedded_v2_archive_records(manifest_name: str) -> list[dict]:
    snapshot = V2_MANIFEST_BUNDLE.get(manifest_name)
    if not isinstance(snapshot, dict):
        raise RuntimeError(f"Embedded package manifest is missing: {manifest_name}")
    raw_files = snapshot.get("files")
    if not isinstance(raw_files, list) or not raw_files:
        raise RuntimeError(f"Embedded package manifest has no files: {manifest_name}")

    records: list[dict] = []
    for position, raw in enumerate(raw_files, start=1):
        if not isinstance(raw, dict):
            raise RuntimeError(
                f"Invalid embedded package record {position}: {manifest_name}"
            )
        relative_path = str(raw.get("relative_path", "")).replace("\\", "/").strip("/")
        url = str(raw.get("url", "")).strip()
        try:
            size_bytes = int(raw.get("size_bytes", 0) or 0)
        except (TypeError, ValueError) as error:
            raise RuntimeError(
                f"Invalid embedded package byte count: {manifest_name} record {position}"
            ) from error
        if not relative_path or not url or size_bytes <= 0:
            raise RuntimeError(
                f"Incomplete embedded package record: {manifest_name} record {position}"
            )
        records.append({
            "url": url,
            "relative_path": relative_path,
            "size_bytes": size_bytes,
            "source": "manifest_v2",
        })
    return records


VIDEO_AI_715_VERIFIED_PACKAGE_RECORDS = embedded_v2_archive_records(
    VIDEO_AI_715_V2_MANIFEST_NAME
)
VIDEO_161_PACKAGE_RECORDS = embedded_v2_archive_records(
    VIDEO_161_EXTRA_V2_MANIFEST_NAME
)
STARLIGHT_25_PACKAGE_RECORDS = embedded_v2_archive_records(
    STARLIGHT_25_V2_MANIFEST_NAME
)

