for line in FILES_RAW.splitlines():
    name = (
        line.strip()
            .replace("\u200e", "")   # Remove hidden Left-to-Right Mark
            .replace("\ufeff", "")   # Remove UTF-8 BOM if present
    )

    if name:
        FILES.append(name)

# Deduplicate the raw-model inventory and sort it alphabetically.


RAW_MODEL_FILES = []

for name in sorted(set(FILES), key=str.lower):
    destination = DEST / name

    RAW_MODEL_FILES.append({
        "url": f"{BASE_URL}/{name}",
        "relative_path": name,
        "filename": name,
        "destination": destination,
        "destination_folder": destination.parent,
        "model_family": "raw",
        "source": "raw_file_list",
        "size": MIRROR_V1_EXPECTED_SIZES.get(name, 0),
    })

