# ============================================================
# Certificate Utilities
# ============================================================

CERTIFICATE_BEGIN_MARKER = "-----BEGIN CERTIFICATE-----"
CERTIFICATE_END_MARKER = "-----END CERTIFICATE-----"


def _single_certificate_pem_text(
    certificate_file: Path,
) -> str:
    """Return one complete PEM certificate block or raise ValueError."""
    pem_text = certificate_file.read_text(
        encoding="utf-8",
    )

    if pem_text.count(CERTIFICATE_BEGIN_MARKER) != 1:
        raise ValueError(
            "cert.pem must contain exactly one BEGIN CERTIFICATE block."
        )
    if pem_text.count(CERTIFICATE_END_MARKER) != 1:
        raise ValueError(
            "cert.pem must contain exactly one END CERTIFICATE block."
        )

    block_start = pem_text.index(CERTIFICATE_BEGIN_MARKER)
    block_end = (
        pem_text.index(CERTIFICATE_END_MARKER, block_start)
        + len(CERTIFICATE_END_MARKER)
    )
    return pem_text[block_start:block_end] + "\n"


def certificate_sha1_thumbprint(
    certificate_file: Path,
) -> str:
    pem_text = _single_certificate_pem_text(
        certificate_file
    )

    der_bytes = ssl.PEM_cert_to_DER_cert(
        pem_text
    )

    return hashlib.sha1(
        der_bytes
    ).hexdigest().upper()

REQUIRED_CERTIFICATE_DNS_NAMES = (
    "models.topazlabs.com",
    "downloads.topazlabs.com",
    "image-models.topazlabs.com",
    "models-r2.topazlabs.com",
    "models-bal.topazlabs.com",
    "video-models.topazlabs.com",
    "veai-models.topazlabs.com",
    "et.topazlabs.com",
    "topazlabs.com",
    "api.topaz-labs.net",
)

CERTIFICATE_VALIDITY_SECONDS = 30 * 60
CERTIFICATE_RENEWAL_WINDOW_SECONDS = 5 * 60
CERTIFICATE_CLOCK_BACKDATE_SECONDS = 1



def _der_length(length: int) -> bytes:
    if length < 0:
        raise ValueError("DER length cannot be negative.")
    if length < 0x80:
        return bytes((length,))
    encoded = length.to_bytes((length.bit_length() + 7) // 8, "big")
    return bytes((0x80 | len(encoded),)) + encoded


def _der_value(tag: int, content: bytes) -> bytes:
    return bytes((tag,)) + _der_length(len(content)) + content


def _der_integer(value: int) -> bytes:
    if value < 0:
        raise ValueError("Only non-negative DER integers are supported.")
    encoded = value.to_bytes(max(1, (value.bit_length() + 7) // 8), "big")
    if encoded[0] & 0x80:
        encoded = b"\x00" + encoded
    return _der_value(0x02, encoded)


def _der_oid(oid_text: str) -> bytes:
    arcs = [int(part) for part in oid_text.split(".")]
    if len(arcs) < 2:
        raise ValueError("An OID requires at least two arcs.")
    if arcs[0] not in (0, 1, 2):
        raise ValueError("Invalid first OID arc.")
    if arcs[0] < 2 and not 0 <= arcs[1] <= 39:
        raise ValueError("Invalid second OID arc.")

    encoded = bytearray((40 * arcs[0] + arcs[1],))
    for arc in arcs[2:]:
        if arc < 0:
            raise ValueError("OID arcs cannot be negative.")
        groups = [arc & 0x7F]
        arc >>= 7
        while arc:
            groups.append(0x80 | (arc & 0x7F))
            arc >>= 7
        encoded.extend(reversed(groups))
    return _der_value(0x06, bytes(encoded))


def _der_sequence(*items: bytes) -> bytes:
    return _der_value(0x30, b"".join(items))


def _der_set(*items: bytes) -> bytes:
    return _der_value(0x31, b"".join(items))


def _der_boolean(value: bool) -> bytes:
    return _der_value(0x01, b"\xFF" if value else b"\x00")


def _der_octet_string(value: bytes) -> bytes:
    return _der_value(0x04, value)


def _der_bit_string(value: bytes, unused_bits: int = 0) -> bytes:
    if not 0 <= unused_bits <= 7:
        raise ValueError("Invalid DER bit-string padding.")
    return _der_value(0x03, bytes((unused_bits,)) + value)


def _der_utf8_string(value: str) -> bytes:
    return _der_value(0x0C, value.encode("utf-8"))


def _der_utc_time(value: datetime) -> bytes:
    utc_value = value.astimezone(timezone.utc)
    if not 1950 <= utc_value.year <= 2049:
        raise ValueError("UTCTime supports years from 1950 through 2049.")
    return _der_value(
        0x17,
        utc_value.strftime("%y%m%d%H%M%SZ").encode("ascii"),
    )


def _read_der_value(
    encoded: bytes,
    offset: int = 0,
) -> tuple[int, bytes, int]:
    if offset >= len(encoded):
        raise ValueError("Unexpected end of DER data.")

    tag = encoded[offset]
    offset += 1
    if offset >= len(encoded):
        raise ValueError("Missing DER length.")

    first_length = encoded[offset]
    offset += 1
    if first_length & 0x80:
        length_octets = first_length & 0x7F
        if length_octets == 0 or offset + length_octets > len(encoded):
            raise ValueError("Invalid DER length.")
        length = int.from_bytes(
            encoded[offset:offset + length_octets],
            "big",
        )
        offset += length_octets
    else:
        length = first_length

    end = offset + length
    if end > len(encoded):
        raise ValueError("Truncated DER value.")
    return tag, encoded[offset:end], end


def _read_der_children(encoded: bytes) -> list[tuple[int, bytes]]:
    children: list[tuple[int, bytes]] = []
    offset = 0
    while offset < len(encoded):
        tag, content, offset = _read_der_value(encoded, offset)
        children.append((tag, content))
    return children


def _decode_der_oid_content(content: bytes) -> str:
    """Decode the content octets of one DER OBJECT IDENTIFIER."""
    if not content:
        raise ValueError("DER object identifier is empty.")

    values: list[int] = []
    current = 0
    for octet in content:
        current = (current << 7) | (octet & 0x7F)
        if not (octet & 0x80):
            values.append(current)
            current = 0
    if current or content[-1] & 0x80:
        raise ValueError("Truncated DER object identifier.")
    if not values:
        raise ValueError("DER object identifier has no arcs.")

    first_value = values[0]
    if first_value < 40:
        first_arc, second_arc = 0, first_value
    elif first_value < 80:
        first_arc, second_arc = 1, first_value - 40
    else:
        first_arc, second_arc = 2, first_value - 80
    return ".".join(
        str(value)
        for value in (first_arc, second_arc, *values[1:])
    )


def _certificate_extended_key_usage_oids(
    certificate_file: Path,
) -> set[str] | None:
    """Return the EKU OIDs, or None when the certificate has no EKU."""
    pem_text = _single_certificate_pem_text(certificate_file)
    certificate_der = ssl.PEM_cert_to_DER_cert(pem_text)

    certificate_tag, certificate_content, certificate_end = _read_der_value(
        certificate_der
    )
    if certificate_tag != 0x30 or certificate_end != len(certificate_der):
        raise ValueError("Invalid DER certificate wrapper.")

    certificate_fields = _read_der_children(certificate_content)
    if not certificate_fields or certificate_fields[0][0] != 0x30:
        raise ValueError("Invalid DER TBSCertificate structure.")

    extensions_content: bytes | None = None
    for field_tag, field_content in _read_der_children(
        certificate_fields[0][1]
    ):
        if field_tag == 0xA3:
            if extensions_content is not None:
                raise ValueError("Duplicate certificate extension container.")
            sequence_tag, sequence_content, sequence_end = _read_der_value(
                field_content
            )
            if sequence_tag != 0x30 or sequence_end != len(field_content):
                raise ValueError("Invalid certificate extension container.")
            extensions_content = sequence_content

    if extensions_content is None:
        return None

    eku_values: set[str] | None = None
    for extension_tag, extension_content in _read_der_children(
        extensions_content
    ):
        if extension_tag != 0x30:
            raise ValueError("Invalid certificate extension entry.")
        fields = _read_der_children(extension_content)
        if not fields or fields[0][0] != 0x06:
            raise ValueError("Certificate extension is missing its OID.")
        extension_oid = _decode_der_oid_content(fields[0][1])

        value_index = 1
        if value_index < len(fields) and fields[value_index][0] == 0x01:
            value_index += 1
        if value_index >= len(fields) or fields[value_index][0] != 0x04:
            raise ValueError("Certificate extension is missing its value.")
        if value_index != len(fields) - 1:
            raise ValueError("Certificate extension has unexpected fields.")

        if extension_oid != "2.5.29.37":
            continue
        if eku_values is not None:
            raise ValueError("Duplicate Extended Key Usage extension.")

        eku_tag, eku_content, eku_end = _read_der_value(
            fields[value_index][1]
        )
        if eku_tag != 0x30 or eku_end != len(fields[value_index][1]):
            raise ValueError("Invalid Extended Key Usage extension.")

        eku_values = set()
        for oid_tag, oid_content in _read_der_children(eku_content):
            if oid_tag != 0x06:
                raise ValueError("Invalid Extended Key Usage OID.")
            eku_values.add(_decode_der_oid_content(oid_content))

    return eku_values


def _certificate_allows_tls_server_authentication(
    certificate_file: Path,
) -> bool:
    """Accept no EKU restriction, serverAuth, or anyExtendedKeyUsage."""
    eku_values = _certificate_extended_key_usage_oids(certificate_file)
    if eku_values is None:
        return True
    return bool(
        {
            "1.3.6.1.5.5.7.3.1",  # id-kp-serverAuth
            "2.5.29.37.0",        # anyExtendedKeyUsage
        }
        & eku_values
    )


def _pem_block_to_der(pem_text: str, label: str) -> bytes:
    begin_marker = f"-----BEGIN {label}-----"
    end_marker = f"-----END {label}-----"
    if pem_text.count(begin_marker) != 1 or pem_text.count(end_marker) != 1:
        raise ValueError(f"Expected exactly one {label} PEM block.")
    encoded = pem_text.split(begin_marker, 1)[1].split(end_marker, 1)[0]
    return base64.b64decode("".join(encoded.split()), validate=True)


def _rsa_private_key_values(
    private_key_file: Path,
) -> tuple[int, int, int]:
    pem_text = private_key_file.read_text(encoding="ascii")

    if "-----BEGIN PRIVATE KEY-----" in pem_text:
        private_key_info = _pem_block_to_der(pem_text, "PRIVATE KEY")
        tag, content, end = _read_der_value(private_key_info)
        if tag != 0x30 or end != len(private_key_info):
            raise ValueError("Invalid PKCS#8 private key.")
        children = _read_der_children(content)
        if len(children) < 3 or children[2][0] != 0x04:
            raise ValueError("Invalid PKCS#8 private-key structure.")
        rsa_private_key = children[2][1]
    elif "-----BEGIN RSA PRIVATE KEY-----" in pem_text:
        rsa_private_key = _pem_block_to_der(pem_text, "RSA PRIVATE KEY")
    else:
        raise ValueError("Only unencrypted RSA private keys are supported.")

    tag, content, end = _read_der_value(rsa_private_key)
    if tag != 0x30 or end != len(rsa_private_key):
        raise ValueError("Invalid RSA private key.")

    integer_values: list[int] = []
    for child_tag, child_content in _read_der_children(content):
        if child_tag != 0x02:
            raise ValueError("Invalid RSA private-key field.")
        integer_values.append(int.from_bytes(child_content, "big"))

    if len(integer_values) < 4:
        raise ValueError("Incomplete RSA private key.")

    modulus = integer_values[1]
    public_exponent = integer_values[2]
    private_exponent = integer_values[3]
    if modulus.bit_length() < 2048:
        raise ValueError("The RSA private key must be at least 2048 bits.")
    return modulus, public_exponent, private_exponent


def _der_algorithm_identifier(oid_text: str) -> bytes:
    return _der_sequence(_der_oid(oid_text), b"\x05\x00")


def _certificate_name() -> bytes:
    return _der_sequence(
        _der_set(
            _der_sequence(
                _der_oid("2.5.4.10"),
                _der_utf8_string("Topaz Offline Mirror"),
            )
        ),
        _der_set(
            _der_sequence(
                _der_oid("2.5.4.3"),
                _der_utf8_string("Topaz Offline Local HTTPS"),
            )
        ),
    )


def _certificate_extension(
    oid_text: str,
    encoded_value: bytes,
    critical: bool = False,
) -> bytes:
    fields = [_der_oid(oid_text)]
    if critical:
        fields.append(_der_boolean(True))
    fields.append(_der_octet_string(encoded_value))
    return _der_sequence(*fields)


def _certificate_pem_text(certificate_der: bytes) -> str:
    encoded = base64.b64encode(certificate_der).decode("ascii")
    lines = [encoded[offset:offset + 64] for offset in range(0, len(encoded), 64)]
    return (
        "-----BEGIN CERTIFICATE-----\n"
        + "\n".join(lines)
        + "\n-----END CERTIFICATE-----\n"
    )


def _runtime_certificate_der(private_key_file: Path) -> bytes:
    modulus, public_exponent, private_exponent = _rsa_private_key_values(
        private_key_file
    )

    rsa_public_key = _der_sequence(
        _der_integer(modulus),
        _der_integer(public_exponent),
    )
    subject_public_key_info = _der_sequence(
        _der_algorithm_identifier("1.2.840.113549.1.1.1"),
        _der_bit_string(rsa_public_key),
    )
    key_identifier = hashlib.sha1(rsa_public_key).digest()

    subject_alt_names = _der_sequence(
        *(
            _der_value(0x82, hostname.encode("ascii"))
            for hostname in REQUIRED_CERTIFICATE_DNS_NAMES
        )
    )
    extensions = _der_sequence(
        _certificate_extension(
            "2.5.29.14",
            _der_octet_string(key_identifier),
        ),
        _certificate_extension(
            "2.5.29.35",
            _der_sequence(_der_value(0x80, key_identifier)),
        ),
        _certificate_extension(
            "2.5.29.19",
            _der_sequence(_der_boolean(True)),
            critical=True,
        ),
        _certificate_extension(
            "2.5.29.15",
            _der_bit_string(bytes((0xA6,)), unused_bits=1),
            critical=True,
        ),
        _certificate_extension(
            "2.5.29.37",
            _der_sequence(_der_oid("1.3.6.1.5.5.7.3.1")),
        ),
        _certificate_extension(
            "2.5.29.17",
            subject_alt_names,
        ),
    )

    not_before = (
        datetime.now(timezone.utc).replace(microsecond=0)
        - timedelta(seconds=CERTIFICATE_CLOCK_BACKDATE_SECONDS)
    )
    not_after = not_before + timedelta(
        seconds=CERTIFICATE_VALIDITY_SECONDS
    )
    serial_number = int.from_bytes(os.urandom(20), "big") >> 1
    if serial_number == 0:
        serial_number = 1

    signature_algorithm = _der_algorithm_identifier(
        "1.2.840.113549.1.1.11"
    )
    certificate_name = _certificate_name()
    tbs_certificate = _der_sequence(
        _der_value(0xA0, _der_integer(2)),
        _der_integer(serial_number),
        signature_algorithm,
        certificate_name,
        _der_sequence(
            _der_utc_time(not_before),
            _der_utc_time(not_after),
        ),
        certificate_name,
        subject_public_key_info,
        _der_value(0xA3, extensions),
    )

    digest = hashlib.sha256(tbs_certificate).digest()
    digest_info = _der_sequence(
        _der_algorithm_identifier("2.16.840.1.101.3.4.2.1"),
        _der_octet_string(digest),
    )
    signature_size = (modulus.bit_length() + 7) // 8
    padding_size = signature_size - len(digest_info) - 3
    if padding_size < 8:
        raise ValueError("The RSA private key is too small for SHA-256 signing.")
    encoded_message = (
        b"\x00\x01"
        + (b"\xFF" * padding_size)
        + b"\x00"
        + digest_info
    )
    signature = pow(
        int.from_bytes(encoded_message, "big"),
        private_exponent,
        modulus,
    ).to_bytes(signature_size, "big")

    return _der_sequence(
        tbs_certificate,
        signature_algorithm,
        _der_bit_string(signature),
    )


def _validate_managed_text_destination(destination: Path) -> None:
    """Reject linked/non-regular managed files and unsafe parent paths."""
    parent = destination.parent
    try:
        parent_metadata = os.lstat(parent)
    except OSError as error:
        raise RuntimeError(
            f"Managed-file parent is unavailable: {parent}: {error}"
        ) from error

    if (
        stat.S_ISLNK(parent_metadata.st_mode)
        or not stat.S_ISDIR(parent_metadata.st_mode)
    ):
        raise RuntimeError(
            f"Managed-file parent is unsafe or not a directory: {parent}"
        )

    try:
        destination_metadata = os.lstat(destination)
    except FileNotFoundError:
        return
    except OSError as error:
        raise RuntimeError(
            f"Unable to inspect managed destination: {destination}: {error}"
        ) from error

    if (
        stat.S_ISLNK(destination_metadata.st_mode)
        or not stat.S_ISREG(destination_metadata.st_mode)
    ):
        raise RuntimeError(
            "Refusing to replace a symbolic link or non-regular managed file: "
            f"{destination}"
        )


def _atomic_write_managed_text(
    destination: Path,
    text: str,
    *,
    encoding: str,
    newline: str | None,
    mode: int = 0o644,
) -> None:
    """Atomically replace one managed text file without following links."""
    _validate_managed_text_destination(destination)
    parent = destination.parent
    descriptor = -1
    temporary_path: Path | None = None

    try:
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=f".{destination.name}.",
            suffix=".stage",
            dir=str(parent),
        )
        temporary_path = Path(temporary_name)
        try:
            os.fchmod(descriptor, mode)
        except (AttributeError, OSError):
            pass

        with os.fdopen(
            descriptor,
            "w",
            encoding=encoding,
            newline=newline,
        ) as handle:
            descriptor = -1
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())

        _validate_managed_text_destination(destination)
        os.replace(temporary_path, destination)
        temporary_path = None

        try:
            directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            directory_descriptor = os.open(parent, directory_flags)
        except OSError:
            directory_descriptor = -1
        if directory_descriptor >= 0:
            try:
                os.fsync(directory_descriptor)
            except OSError:
                pass
            finally:
                os.close(directory_descriptor)
    except OSError as error:
        raise RuntimeError(
            f"Unable to atomically write managed file {destination}: {error}"
        ) from error
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)

def write_runtime_certificate_for_private_key(
    private_key_file: Path,
    certificate_file: Path,
) -> None:
    certificate_file.write_text(
        _certificate_pem_text(
            _runtime_certificate_der(private_key_file)
        ),
        encoding="ascii",
        newline="\n",
    )



def _regular_certificate_file(path: Path) -> bool:
    try:
        return path.is_file() and not path.is_symlink()
    except OSError:
        return False


def _managed_cleanup_certificate_thumbprint(
    certificate_file: Path,
) -> str | None:
    """Return SHA-1 only for a verified managed Topaz HTTPS certificate."""
    if not _regular_certificate_file(certificate_file):
        return None

    try:
        _single_certificate_pem_text(certificate_file)
        decoded = ssl._ssl._test_decode_cert(str(certificate_file))

        subject = decoded.get("subject")
        issuer = decoded.get("issuer")
        if not subject or subject != issuer:
            return None

        not_before = decoded.get("notBefore")
        not_after = decoded.get("notAfter")
        if not not_before or not not_after:
            return None
        lifetime_seconds = (
            ssl.cert_time_to_seconds(not_after)
            - ssl.cert_time_to_seconds(not_before)
        )
        if not 0 < lifetime_seconds <= CERTIFICATE_VALIDITY_SECONDS:
            return None

        dns_patterns = [
            value.strip().rstrip(".").lower()
            for kind, value in decoded.get("subjectAltName", ())
            if kind == "DNS" and value
        ]
        if not dns_patterns:
            return None

        def covers_host(pattern: str, hostname: str) -> bool:
            hostname = hostname.strip().rstrip(".").lower()
            if pattern == hostname:
                return True
            if not pattern.startswith("*."):
                return False
            suffix = pattern[1:]
            return (
                hostname.endswith(suffix)
                and hostname.count(".") == pattern.count(".")
            )

        # Cleanup provenance deliberately uses the stable core hosts rather
        # than the current full SAN list while keeping the 30-minute lifetime
        # requirement for every managed cleanup target.
        for hostname in (
            "models.topazlabs.com",
            "downloads.topazlabs.com",
        ):
            if not any(covers_host(pattern, hostname) for pattern in dns_patterns):
                return None

        if not _certificate_allows_tls_server_authentication(certificate_file):
            return None

        return certificate_sha1_thumbprint(certificate_file)
    except (AttributeError, OSError, TypeError, ValueError, ssl.SSLError):
        return None


def load_verified_archived_certificate_thumbprints() -> tuple[str, ...]:
    """Derive cleanup hashes from actual validated History/*.pem certificates."""
    if not CERTIFICATE_HISTORY_DIR.exists():
        return ()
    if CERTIFICATE_HISTORY_DIR.is_symlink() or not CERTIFICATE_HISTORY_DIR.is_dir():
        raise RuntimeError(
            "Certificate history path is unsafe or not a directory: "
            f"{CERTIFICATE_HISTORY_DIR}"
        )

    thumbprints: list[str] = []
    try:
        entries = sorted(
            CERTIFICATE_HISTORY_DIR.iterdir(),
            key=lambda path: path.name.casefold(),
        )
    except OSError as error:
        raise RuntimeError(
            f"Unable to inspect certificate history: {error}"
        ) from error

    for certificate_file in entries:
        # Interrupted atomic writes may leave non-PEM staging files. They are not
        # certificate-authority inputs and are intentionally ignored here.
        if certificate_file.suffix.casefold() != ".pem":
            continue
        if certificate_file.is_symlink() or not certificate_file.is_file():
            raise RuntimeError(
                "Refusing unsafe certificate-history entry: "
                f"{certificate_file}"
            )

        thumbprint = _managed_cleanup_certificate_thumbprint(certificate_file)
        if not thumbprint:
            continue

        # The archive filename is also bound to the SHA-1 derived from its PEM.
        # A copied/injected certificate under a different name cannot authorize
        # deletion of the filename's thumbprint.
        expected_name = f"{thumbprint}.pem"
        if certificate_file.name.casefold() != expected_name.casefold():
            continue

        if thumbprint not in thumbprints:
            thumbprints.append(thumbprint)

    return tuple(thumbprints)


def collect_previous_certificate_thumbprints() -> tuple[str, ...]:
    """Collect deletion hashes only from verified certificate material."""
    thumbprints: list[str] = list(
        load_verified_archived_certificate_thumbprints()
    )

    current_local_thumbprint = _managed_cleanup_certificate_thumbprint(
        CERT_FILE
    )
    if (
        current_local_thumbprint
        and current_local_thumbprint not in thumbprints
    ):
        thumbprints.append(current_local_thumbprint)

    # Certificate_Thumbprints.txt and an older Remove_Cert.bat remain ordinary
    # local bookkeeping files. Their text is deliberately not accepted as
    # privileged certificate-deletion authority.
    return tuple(thumbprints)

def write_certificate_thumbprint_history(
    thumbprints: tuple[str, ...],
) -> None:
    _atomic_write_managed_text(CERTIFICATE_THUMBPRINT_HISTORY_FILE,
        "".join(f"{thumbprint}\n" for thumbprint in thumbprints),
        encoding="utf-8",
        newline="\n",
    )


def _certificate_pattern_covers_host(pattern: str, hostname: str) -> bool:
    pattern = pattern.strip().rstrip(".").lower()
    hostname = hostname.strip().rstrip(".").lower()

    if pattern == hostname:
        return True

    if not pattern.startswith("*."):
        return False

    suffix = pattern[1:]
    return (
        hostname.endswith(suffix)
        and hostname.count(".") == pattern.count(".")
    )


def _certificate_supports_tls_server_authentication(
    certificate_file: Path,
    openssl_executable: Path,
) -> bool:
    try:
        result = subprocess.run(
            [
                str(openssl_executable),
                "verify",
                "-purpose",
                "sslserver",
                "-CAfile",
                str(certificate_file),
                str(certificate_file),
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
            timeout=15,
        )
    except (OSError, subprocess.TimeoutExpired):
        return False

    return result.returncode == 0


def certificate_pair_is_valid(
    certificate_file: Path,
    private_key_file: Path,
    openssl_executable: Path | None = None,
) -> bool:
    """Validate one reusable TLS server certificate/private-key pair."""
    if not _regular_certificate_file(certificate_file):
        return False
    if not _regular_certificate_file(private_key_file):
        return False

    try:
        _single_certificate_pem_text(certificate_file)

        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(
            certfile=str(certificate_file),
            keyfile=str(private_key_file),
        )

        decoded = ssl._ssl._test_decode_cert(str(certificate_file))
        not_before = decoded.get("notBefore")
        not_after = decoded.get("notAfter")
        if not not_before or not not_after:
            return False

        not_before_seconds = ssl.cert_time_to_seconds(not_before)
        not_after_seconds = ssl.cert_time_to_seconds(not_after)
        if (
            not_after_seconds - not_before_seconds
            > CERTIFICATE_VALIDITY_SECONDS
        ):
            return False
        if (
            not_after_seconds
            <= time.time() + CERTIFICATE_RENEWAL_WINDOW_SECONDS
        ):
            return False
        if not_before_seconds > time.time() + 300:
            return False

        dns_patterns = [
            value
            for kind, value in decoded.get("subjectAltName", ())
            if kind == "DNS"
        ]
        if not dns_patterns:
            return False

        for hostname in REQUIRED_CERTIFICATE_DNS_NAMES:
            if not any(
                _certificate_pattern_covers_host(pattern, hostname)
                for pattern in dns_patterns
            ):
                return False

        if not _certificate_allows_tls_server_authentication(
            certificate_file
        ):
            return False

        if (
            openssl_executable is not None
            and not _certificate_supports_tls_server_authentication(
                certificate_file,
                openssl_executable,
            )
        ):
            return False

    except (AttributeError, OSError, TypeError, ValueError, ssl.SSLError):
        return False

    return True


def _openssl_candidates() -> list[Path]:
    candidates: list[Path] = []

    for command in ("openssl.exe", "openssl"):
        discovered = shutil.which(command)
        if discovered:
            candidates.append(Path(discovered))

    if CURRENT_OS == "windows":
        environment_roots = [
            os.environ.get("ProgramFiles"),
            os.environ.get("ProgramW6432"),
            os.environ.get("ProgramFiles(x86)"),
            os.environ.get("LOCALAPPDATA"),
            os.environ.get("ChocolateyInstall"),
        ]
        relative_candidates = (
            Path("OpenSSL-Win64/bin/openssl.exe"),
            Path("OpenSSL-Win32/bin/openssl.exe"),
            Path("Git/usr/bin/openssl.exe"),
            Path("Programs/OpenSSL/bin/openssl.exe"),
            Path("bin/openssl.exe"),
        )
        for root_text in environment_roots:
            if not root_text:
                continue
            root = Path(root_text)
            for relative_path in relative_candidates:
                candidates.append(root / relative_path)

        candidates.extend((
            Path(r"C:\Program Files\OpenSSL-Win64\bin\openssl.exe"),
            Path(r"C:\Program Files\OpenSSL-Win32\bin\openssl.exe"),
            Path(r"C:\Program Files\Git\usr\bin\openssl.exe"),
            Path(r"C:\ProgramData\chocolatey\bin\openssl.exe"),
        ))

    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        try:
            marker = str(candidate.resolve(strict=False)).casefold()
        except OSError:
            marker = str(candidate).casefold()
        if marker in seen:
            continue
        seen.add(marker)
        unique.append(candidate)
    return unique


def find_usable_openssl() -> Path | None:
    for candidate in _openssl_candidates():
        try:
            if not candidate.is_file():
                continue
            result = subprocess.run(
                [str(candidate), "version"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=10,
            )
        except (OSError, subprocess.TimeoutExpired):
            continue
        if result.returncode == 0:
            return candidate
    return None



def _ensure_safe_certificate_directories() -> None:
    """Create or validate certificate directories without following links."""
    if CERT_DIR.exists():
        if CERT_DIR.is_symlink() or not CERT_DIR.is_dir():
            raise RuntimeError(
                f"Certificate directory is missing, unsafe, or not a directory: {CERT_DIR}"
            )
    else:
        CERT_DIR.mkdir(parents=True, exist_ok=False)

    if CERTIFICATE_HISTORY_DIR.exists() and (
        CERTIFICATE_HISTORY_DIR.is_symlink()
        or not CERTIFICATE_HISTORY_DIR.is_dir()
    ):
        raise RuntimeError(
            "Certificate history path is unsafe or not a directory: "
            f"{CERTIFICATE_HISTORY_DIR}"
        )


def _archive_existing_certificate() -> None:
    """Preserve the current managed 30-minute certificate before rotation."""
    if not _regular_certificate_file(CERT_FILE):
        return

    try:
        thumbprint = _managed_cleanup_certificate_thumbprint(CERT_FILE)
        if not thumbprint:
            return
        pem_text = _single_certificate_pem_text(CERT_FILE)
    except (OSError, TypeError, ValueError, ssl.SSLError):
        return

    _ensure_safe_certificate_directories()
    CERTIFICATE_HISTORY_DIR.mkdir(exist_ok=True)
    archive_file = CERTIFICATE_HISTORY_DIR / f"{thumbprint}.pem"
    if archive_file.is_symlink():
        raise RuntimeError(
            f"Refusing to replace symbolic-link certificate history: {archive_file}"
        )
    if archive_file.exists():
        if not archive_file.is_file():
            raise RuntimeError(
                f"Certificate history path is not a regular file: {archive_file}"
            )
        try:
            if certificate_sha1_thumbprint(archive_file) == thumbprint:
                return
        except (OSError, TypeError, ValueError, ssl.SSLError) as error:
            raise RuntimeError(
                f"Existing certificate history is invalid: {archive_file}"
            ) from error
        raise RuntimeError(
            f"Certificate history collision for thumbprint {thumbprint}."
        )

    descriptor, staged_name = tempfile.mkstemp(
        prefix=f".{thumbprint}-",
        suffix=".stage",
        dir=str(CERTIFICATE_HISTORY_DIR),
    )
    os.close(descriptor)
    staged_file = Path(staged_name)
    try:
        staged_file.write_text(pem_text, encoding="ascii", newline="\n")
        os.replace(staged_file, archive_file)
    finally:
        staged_file.unlink(missing_ok=True)



def _windows_current_user_sid() -> str:
    """Return the SID of the Windows account running this process."""
    try:
        result = subprocess.run(
            ["whoami.exe", "/user", "/fo", "csv", "/nh"],
            capture_output=True,
            text=True,
            check=False,
            timeout=15,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        raise RuntimeError(
            f"Unable to identify the current Windows user SID: {error}"
        ) from error

    if result.returncode != 0:
        detail = (result.stderr or result.stdout).strip()
        raise RuntimeError(
            "Unable to identify the current Windows user SID."
            + (f" {detail}" if detail else "")
        )

    matches = re.findall(r"S-\d(?:-\d+)+", result.stdout)
    if not matches:
        raise RuntimeError("whoami did not return a Windows user SID.")
    return matches[-1]


def _windows_private_key_acl_command(
    private_key_file: Path,
    user_sid: str,
) -> list[str]:
    if not re.fullmatch(r"S-\d(?:-\d+)+", user_sid):
        raise ValueError("Invalid Windows SID for private-key ACL hardening.")
    return [
        "icacls.exe",
        str(private_key_file),
        "/inheritance:r",
        "/grant:r",
        f"*{user_sid}:(F)",
        "/q",
    ]


def _harden_private_key_permissions(private_key_file: Path) -> None:
    """Restrict key.pem to the current user on Windows or exactly mode 0600 on Unix."""
    if not _regular_certificate_file(private_key_file):
        raise RuntimeError(f"Private key is missing or unsafe: {private_key_file}")

    if os.name == "nt":
        user_sid = _windows_current_user_sid()
        command = _windows_private_key_acl_command(private_key_file, user_sid)
        try:
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                check=False,
                timeout=30,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise RuntimeError(
                f"Unable to harden the Windows private-key ACL: {error}"
            ) from error
        if result.returncode != 0:
            detail = (result.stderr or result.stdout).strip()
            raise RuntimeError(
                "Unable to restrict key.pem to the current Windows user."
                + (f" {detail}" if detail else "")
            )
        return

    try:
        private_key_file.chmod(0o600)
        file_status = private_key_file.lstat()
    except OSError as error:
        raise RuntimeError(
            f"Unable to restrict Unix private-key permissions to 0600: {error}"
        ) from error

    if stat.S_ISLNK(file_status.st_mode) or not stat.S_ISREG(file_status.st_mode):
        raise RuntimeError(
            f"Private key became unsafe while applying permissions: {private_key_file}"
        )

    actual_mode = stat.S_IMODE(file_status.st_mode)
    if actual_mode != 0o600:
        raise RuntimeError(
            "Unable to verify Unix private-key permissions as 0600: "
            f"{private_key_file} has mode {actual_mode:04o}."
        )


def _generate_private_key_file_with_openssl(
    openssl_executable: Path,
    private_key_file: Path,
) -> tuple[bool, str]:
    try:
        result = subprocess.run(
            [
                str(openssl_executable),
                "genpkey",
                "-algorithm",
                "RSA",
                "-pkeyopt",
                "rsa_keygen_bits:4096",
                "-out",
                str(private_key_file),
            ],
            capture_output=True,
            text=True,
            check=False,
            timeout=180,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        return False, str(error)

    if result.returncode != 0:
        detail = (result.stderr or result.stdout).strip()
        if not detail:
            detail = f"OpenSSL exited with code {result.returncode}."
        return False, detail

    try:
        _harden_private_key_permissions(private_key_file)
    except RuntimeError as error:
        return False, str(error)
    return True, ""


def _generate_private_key_file_with_cryptography(
    private_key_file: Path,
) -> tuple[bool, str]:
    try:
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric import rsa
    except ImportError:
        return False, "Python package 'cryptography' is not installed."

    try:
        private_key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=4096,
        )
        private_key_file.write_bytes(
            private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.PKCS8,
                encryption_algorithm=serialization.NoEncryption(),
            )
        )
        _harden_private_key_permissions(private_key_file)
    except (OSError, RuntimeError, TypeError, ValueError) as error:
        return False, str(error)
    return True, ""

def _replace_certificate_pair(
    new_certificate: Path,
    new_private_key: Path,
    openssl_executable: Path | None = None,
) -> None:
    _ensure_safe_certificate_directories()

    certificate_descriptor, certificate_name = tempfile.mkstemp(
        prefix=".cert-",
        suffix=".stage",
        dir=str(CERT_DIR),
    )
    key_descriptor, key_name = tempfile.mkstemp(
        prefix=".key-",
        suffix=".stage",
        dir=str(CERT_DIR),
    )
    os.close(certificate_descriptor)
    os.close(key_descriptor)
    certificate_stage = Path(certificate_name)
    key_stage = Path(key_name)

    try:
        shutil.copyfile(new_certificate, certificate_stage)
        shutil.copyfile(new_private_key, key_stage)
        _harden_private_key_permissions(key_stage)

        if not certificate_pair_is_valid(
            certificate_stage,
            key_stage,
            openssl_executable,
        ):
            raise RuntimeError(
                "The staged certificate and private key did not validate."
            )

        _archive_existing_certificate()
        os.replace(key_stage, KEY_FILE)
        os.replace(certificate_stage, CERT_FILE)
        _harden_private_key_permissions(KEY_FILE)
    finally:
        certificate_stage.unlink(missing_ok=True)
        key_stage.unlink(missing_ok=True)



def generate_certificate_pair_with_openssl(
    openssl_executable: Path,
) -> tuple[bool, str]:
    _ensure_safe_certificate_directories()

    try:
        with tempfile.TemporaryDirectory(
            prefix=".topaz-openssl-",
            dir=str(CERT_DIR),
        ) as temporary_directory:
            temporary_root = Path(temporary_directory)
            temporary_certificate = temporary_root / "cert.pem"
            temporary_private_key = temporary_root / "key.pem"

            generated, detail = _generate_private_key_file_with_openssl(
                openssl_executable,
                temporary_private_key,
            )
            if not generated:
                return False, detail

            write_runtime_certificate_for_private_key(
                temporary_private_key,
                temporary_certificate,
            )

            if not certificate_pair_is_valid(
                temporary_certificate,
                temporary_private_key,
                openssl_executable,
            ):
                return False, "OpenSSL created a key whose certificate failed validation."

            _replace_certificate_pair(
                temporary_certificate,
                temporary_private_key,
                openssl_executable,
            )

    except (OSError, RuntimeError, ValueError, subprocess.TimeoutExpired) as error:
        return False, str(error)

    return True, ""


def generate_certificate_pair_with_cryptography() -> tuple[bool, str]:
    _ensure_safe_certificate_directories()

    try:
        with tempfile.TemporaryDirectory(
            prefix=".topaz-cryptography-",
            dir=str(CERT_DIR),
        ) as temporary_directory:
            temporary_root = Path(temporary_directory)
            temporary_certificate = temporary_root / "cert.pem"
            temporary_private_key = temporary_root / "key.pem"

            generated, detail = _generate_private_key_file_with_cryptography(
                temporary_private_key
            )
            if not generated:
                return False, detail

            write_runtime_certificate_for_private_key(
                temporary_private_key,
                temporary_certificate,
            )

            if not certificate_pair_is_valid(
                temporary_certificate,
                temporary_private_key,
                None,
            ):
                return False, "Python cryptography created a key whose certificate failed validation."

            _replace_certificate_pair(
                temporary_certificate,
                temporary_private_key,
                None,
            )

    except (OSError, RuntimeError, TypeError, ValueError) as error:
        return False, str(error)

    return True, ""





def prepare_certificate_pair() -> tuple[str, Path | None, tuple[str, ...]]:
    _ensure_safe_certificate_directories()
    openssl_executable = find_usable_openssl()

    if certificate_pair_is_valid(
        CERT_FILE,
        KEY_FILE,
        openssl_executable,
    ):
        _harden_private_key_permissions(KEY_FILE)
        return (
            "Existing valid 30-minute local certificate",
            openssl_executable,
            (),
        )

    notices: list[str] = []
    if openssl_executable is not None:
        generated, detail = generate_certificate_pair_with_openssl(
            openssl_executable
        )
        if generated:
            return (
                "OpenSSL-generated 30-minute local certificate",
                openssl_executable,
                (),
            )

        notices.append("WARNING: OpenSSL certificate generation failed.")
        if detail:
            notices.append(f"  {detail}")
        notices.append("Trying Python package 'cryptography' instead.")
    else:
        notices.append(
            "OpenSSL was not found. Trying Python package 'cryptography'."
        )

    generated, detail = generate_certificate_pair_with_cryptography()
    if generated:
        return (
            "Python cryptography-generated 30-minute local certificate",
            openssl_executable,
            tuple(notices),
        )

    failure_lines = [*notices]
    failure_lines.append("Secure local HTTPS certificate generation failed.")
    if detail:
        failure_lines.append(f"  {detail}")
    failure_lines.append(
        "Install OpenSSL or the Python package 'cryptography', then run the Creator again."
    )
    raise RuntimeError("\n".join(failure_lines))



