def read_recovery_urls(report_file: Path) -> list[str]:
    if report_file.is_symlink() or not report_file.is_file():
        return []

    urls = []
    seen = set()
    try:
        report_text = report_file.read_text(
            encoding="utf-8",
            errors="replace",
        )
        lines = [
            line[:-1] if line.endswith("\r") else line
            for line in report_text.split("\n")
        ]
    except OSError as error:
        print(f"Unable to read recovery report: {error}")
        return []

    for line in lines:
        value = line.strip()
        if not value.startswith("URL : "):
            continue
        value = value[6:].strip()
        if not value or any(
            not character.isprintable()
            for character in value
        ):
            continue
        try:
            parsed = urlparse(value)
            host = parsed.hostname.rstrip(".").lower() if parsed.hostname else ""
            port = parsed.port
        except (TypeError, ValueError):
            continue
        if host not in RECOVERABLE_HOSTS:
            continue
        if parsed.scheme == "http":
            if host != "models.topazlabs.com" or port not in (None, 80):
                continue
        elif parsed.scheme == "https":
            if port not in (None, 443):
                continue
        else:
            continue
        if parsed.username or parsed.password or parsed.fragment:
            continue
        if value in seen:
            continue
        seen.add(value)
        urls.append(value)

    return urls


def mark_recovery_url_fixed(
    report_file: Path,
    url: str,
) -> bool:
    """
    Change unresolved URL entries to REPORTED-FIXED while
    preserving every other diagnostic line in the report.
    """
    if report_file.is_symlink() or not report_file.is_file():
        return False

    try:
        with report_file.open(
            "r",
            encoding="utf-8",
            errors="replace",
            newline="",
        ) as handle:
            report_lines = handle.readlines()

    except OSError as error:
        print(f"Unable to read recovery report: {error}")
        return False

    unresolved_entries = {
        f"URL : {url}",
        url,
    }

    updated_lines = []
    changed = False

    for raw_line in report_lines:
        content = raw_line.rstrip("\r\n")
        line_ending = raw_line[len(content):]
        stripped = content.strip()

        if stripped in unresolved_entries:
            leading_spaces = content[:len(content) - len(content.lstrip())]

            updated_lines.append(
                f"{leading_spaces}REPORTED-FIXED : {url}"
                f"{line_ending}"
            )
            changed = True
        else:
            updated_lines.append(raw_line)

    if not changed:
        return False

    temporary_file = None

    try:
        fd, temporary_name = tempfile.mkstemp(
            prefix=report_file.name + ".",
            suffix=".update",
            dir=report_file.parent,
        )
        temporary_file = Path(temporary_name)
        os.chmod(temporary_file, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.writelines(updated_lines)
            handle.flush()
            os.fsync(handle.fileno())

        if report_file.is_symlink():
            raise OSError("Recovery report became a symbolic link.")
        os.replace(temporary_file, report_file)

    except OSError as error:
        if temporary_file is not None:
            temporary_file.unlink(missing_ok=True)
        print(f"Unable to update recovery report: {error}")
        return False

    return True


def mark_recovery_url_rejected(report_file: Path, url: str) -> bool:
    """Retire a stale wrong-owner V2 recovery entry."""
    if report_file.is_symlink() or not report_file.is_file():
        return False
    try:
        with report_file.open(
            "r", encoding="utf-8", errors="replace", newline=""
        ) as handle:
            report_lines = handle.readlines()
    except OSError as error:
        print(f"Unable to read recovery report: {error}")
        return False

    unresolved_entries = {f"URL : {url}", url}
    updated_lines = []
    changed = False
    for raw_line in report_lines:
        content = raw_line.rstrip("\r\n")
        line_ending = raw_line[len(content):]
        stripped = content.strip()
        if stripped in unresolved_entries:
            leading_spaces = content[:len(content) - len(content.lstrip())]
            updated_lines.append(
                f"{leading_spaces}REPORTED-REJECTED : {url}{line_ending}"
            )
            changed = True
        else:
            updated_lines.append(raw_line)
    if not changed:
        return False

    temporary_file = None
    try:
        fd, temporary_name = tempfile.mkstemp(
            prefix=report_file.name + ".",
            suffix=".update",
            dir=report_file.parent,
        )
        temporary_file = Path(temporary_name)
        os.chmod(temporary_file, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.writelines(updated_lines)
            handle.flush()
            os.fsync(handle.fileno())
        if report_file.is_symlink():
            raise OSError("Recovery report became a symbolic link.")
        os.replace(temporary_file, report_file)
    except OSError as error:
        if temporary_file is not None:
            temporary_file.unlink(missing_ok=True)
        print(f"Unable to update recovery report: {error}")
        return False
    return True

def get_active_hosts_mappings(
    hosts_file: Path,
) -> dict[str, str]:
    mappings = {}

    try:
        lines = hosts_file.read_text(
            encoding="utf-8",
            errors="replace",
        ).splitlines()
    except OSError as error:
        raise RuntimeError(
            f"Unable to read hosts file: {hosts_file}\n{error}"
        ) from error

    for raw_line in lines:
        active_line = raw_line.split("#", 1)[0].strip()

        if not active_line:
            continue

        fields = active_line.split()

        if len(fields) < 2:
            continue

        address = fields[0]

        for hostname in fields[1:]:
            normalized = hostname.rstrip(".").lower()

            if normalized:
                mappings[normalized] = address

    return mappings


def validate_recovery_hosts(urls: list[str]) -> bool:
    hosts_file = get_hosts_file_path()

    try:
        mappings = get_active_hosts_mappings(hosts_file)
    except RuntimeError as error:
        print()
        print("Recovery cancelled.")
        print(error)
        print()
        return False

    blocked = []

    for url in urls:
        host = urlparse(url).hostname

        if not host:
            blocked.append((url, "invalid URL"))
            continue

        normalized = host.rstrip(".").lower()

        if normalized in mappings:
            blocked.append(
                (
                    normalized,
                    mappings[normalized],
                )
            )

    if not blocked:
        return True

    print()
    print("Recovery download blocked.")
    print(f"Hosts file: {hosts_file}")
    print()

    for host, mapping in blocked:
        print(f"  {host} -> {mapping}")

    print()
    print(
        "Remove or comment out the listed hosts entries "
        "before running recovery."
    )
    print("No recovery files were downloaded.")
    print()

    return False

def decoded_recovery_filesystem_path(raw_path: str) -> str | None:
    """Decode an approved URL path into the same path the repeater serves."""
    path = str(raw_path or "")
    if not path or re.search(r"%(?![0-9A-Fa-f]{2})", path):
        return None

    for _ in range(8):
        if any(not character.isprintable() for character in path):
            return None
        if "\\" in path or re.search(r"%(?:2[fF]|5[cC])", path):
            return None
        next_path = unquote(path)
        if next_path == path:
            break
        path = next_path
    else:
        return None

    if not path.startswith("/"):
        path = "/" + path

    components = path.split("/")
    if any(
        component in (".", "..") or ":" in component
        for component in components
    ):
        return None

    normalized_components = [component for component in components if component]
    if not normalized_components:
        return None

    return "/" + "/".join(normalized_components)


def build_recovery_v2_indexes():
    physical_by_path = {
        str(record["relative_path"]).casefold(): dict(record)
        for record in validated_v2_physical_records()
    }
    integrity_by_destination = {}
    routes = set()
    canonical_paths = {}

    for item in current_logical_inventory_records():
        relative = str(item["relative_path"]).replace("\\", "/").strip("/")
        physical = physical_by_path.get(relative.casefold())
        if physical is None:
            raise RuntimeError(f"V2 recovery path is missing from physical inventory: {relative}")
        parsed = urlparse(str(item["url"]))
        scheme = parsed.scheme.lower()
        host = parsed.hostname.rstrip(".").lower() if parsed.hostname else ""
        route_path = "/" + relative
        if parsed.path != route_path:
            raise RuntimeError(f"V2 recovery URL/path mismatch: {item['url']}")
        routes.add((scheme, host, route_path))
        previous = canonical_paths.get(route_path.casefold())
        if previous is not None and previous != route_path:
            raise RuntimeError("V2 recovery paths differ only by case.")
        canonical_paths[route_path.casefold()] = route_path

        destination = MIRROR_ROOT.joinpath(*PurePosixPath(relative).parts).resolve()
        key = str(destination).casefold()
        integrity = (
            int(physical["size_bytes"]),
            str(physical["sha256"]).upper(),
        )
        existing = integrity_by_destination.get(key)
        if existing is not None and existing != integrity:
            raise RuntimeError(f"V2 recovery integrity conflict: {relative}")
        integrity_by_destination[key] = integrity

    expected_physical_count = len(physical_by_path)
    if len(integrity_by_destination) != expected_physical_count:
        raise RuntimeError(
            "V2 recovery integrity coverage is incomplete: "
            f"{len(integrity_by_destination)} of {expected_physical_count}."
        )
    return integrity_by_destination, routes, canonical_paths


RECOVERY_V2_INTEGRITY, RECOVERY_V2_ROUTES, RECOVERY_V2_CANONICAL_PATHS = (
    build_recovery_v2_indexes()
)


CAPTURED_PACKAGE_RECOVERY_ROUTES: set[tuple[str, str, str]] = set()
CAPTURED_PACKAGE_RECOVERY_CANONICAL_PATHS: dict[str, str] = {}
for record in VIDEO_AI_715_CAPTURED_PACKAGE_RECORDS:
    parsed = urlparse(str(record["url"]))
    relative = str(record["relative_path"]).replace("\\", "/").strip("/")
    route_path = "/" + relative
    host = parsed.hostname.rstrip(".").lower() if parsed.hostname else ""
    route_key = (parsed.scheme.lower(), host, route_path)
    CAPTURED_PACKAGE_RECOVERY_ROUTES.add(route_key)
    previous = CAPTURED_PACKAGE_RECOVERY_CANONICAL_PATHS.get(route_path.casefold())
    if previous is not None and previous != route_path:
        raise RuntimeError("Captured package recovery paths differ only by case.")
    CAPTURED_PACKAGE_RECOVERY_CANONICAL_PATHS[route_path.casefold()] = route_path


def recovery_expected_integrity(path: Path) -> tuple[int, str]:
    known = RECOVERY_V2_INTEGRITY.get(str(path.resolve()).casefold())
    if known is not None:
        return known
    try:
        relative = path.resolve().relative_to(MIRROR_ROOT.resolve()).as_posix()
    except (OSError, ValueError):
        return (0, "")
    key = relative.casefold()
    for record in (*load_discovered_inventory_records(), *load_discovered_asset_records()):
        if record["relative_path"].casefold() == key:
            return int(record["size_bytes"]), str(record["sha256"]).upper()
    return (0, "")






def recovery_url_known_v2_route_status(url: str) -> str:
    """Return owned, denied, or unknown for a recovery URL."""
    try:
        parsed = urlparse(url)
        host = parsed.hostname.rstrip(".").lower() if parsed.hostname else ""
    except (TypeError, ValueError):
        return "unknown"
    decoded_path = decoded_recovery_filesystem_path(parsed.path)
    if decoded_path is None:
        return "unknown"
    canonical = RECOVERY_V2_CANONICAL_PATHS.get(decoded_path.casefold())
    route_set = RECOVERY_V2_ROUTES
    if canonical is None:
        canonical = CAPTURED_PACKAGE_RECOVERY_CANONICAL_PATHS.get(
            decoded_path.casefold()
        )
        route_set = CAPTURED_PACKAGE_RECOVERY_ROUTES
    if canonical is None:
        return "unknown"
    if decoded_path != canonical:
        return "denied"
    if (parsed.scheme.lower(), host, canonical) in route_set:
        return "owned"
    return "denied"


def recovery_destination(url: str) -> Path | None:
    try:
        parsed = urlparse(url)
        port = parsed.port
    except (TypeError, ValueError):
        return None

    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        return None

    decoded_path = decoded_recovery_filesystem_path(parsed.path)
    if decoded_path is None:
        return None

    normalized_path = decoded_path.casefold()
    host = parsed.hostname.rstrip(".").lower()

    known_v2_path = RECOVERY_V2_CANONICAL_PATHS.get(normalized_path)
    if known_v2_path is not None:
        if decoded_path != known_v2_path:
            return None
        if parsed.scheme == "http":
            if port not in (None, 80):
                return None
        elif port not in (None, 443):
            return None
        if (parsed.scheme, host, known_v2_path) not in RECOVERY_V2_ROUTES:
            return None
        path_parts = tuple(PurePosixPath(known_v2_path.lstrip("/")).parts)
        destination = MIRROR_ROOT.joinpath(*path_parts)
        try:
            destination.resolve().relative_to(MIRROR_ROOT.resolve())
        except ValueError:
            return None
        if mirror_path_has_link_component(destination):
            return None
        return destination

    captured_package_path = CAPTURED_PACKAGE_RECOVERY_CANONICAL_PATHS.get(
        normalized_path
    )
    if captured_package_path is not None:
        if decoded_path != captured_package_path:
            return None
        if parsed.scheme != "https" or port not in (None, 443):
            return None
        if (parsed.scheme, host, captured_package_path) not in CAPTURED_PACKAGE_RECOVERY_ROUTES:
            return None
        destination = MIRROR_ROOT.joinpath(
            *PurePosixPath(captured_package_path.lstrip("/")).parts
        )
        try:
            destination.resolve().relative_to(MIRROR_ROOT.resolve())
        except ValueError:
            return None
        if mirror_path_has_link_component(destination):
            return None
        return destination

    if (
        normalized_path in BLOCKED_RECOVERY_PATHS
        or normalized_path.startswith(BLOCKED_RECOVERY_PREFIXES)
    ):
        return None

    if parsed.scheme == "http":
        if host != "models.topazlabs.com" or port not in (None, 80):
            return None
    elif port not in (None, 443):
        return None

    # Reject API, telemetry, and other hosts not approved for
    # automatic static-file recovery.
    if host not in RECOVERABLE_HOSTS:
        return None

    if not any(
        normalized_path.endswith(suffix)
        for suffix in RECOVERABLE_SUFFIXES
    ):
        return None

    path_parts = tuple(
        component
        for component in decoded_path.lstrip("/").split("/")
        if component
    )
    destination = MIRROR_ROOT.joinpath(*path_parts)

    try:
        destination.resolve().relative_to(MIRROR_ROOT.resolve())
    except ValueError:
        return None
    if mirror_path_has_link_component(destination):
        return None

    return destination


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest().upper()


def recovery_file_is_usable(
    path: Path,
    expected_size: int = 0,
    expected_sha256: str = "",
    *,
    content_suffix: str | None = None,
) -> bool:
    try:
        if mirror_path_has_link_component(path) or not path.is_file():
            return False

        actual_size = path.stat().st_size

        if actual_size == 0:
            return False

        if expected_size > 0 and actual_size != expected_size:
            return False

        expected_sha256 = str(expected_sha256 or "").upper()
        if expected_sha256:
            if not re.fullmatch(r"[0-9A-F]{64}", expected_sha256):
                return False
            # For authoritative V2 files, the exact SHA-256 already proves the
            # complete bytes. Avoid an additional expensive archive test.
            return sha256_file(path) == expected_sha256

        with path.open("rb") as handle:
            prefix = handle.read(512).lstrip().lower()

        if prefix.startswith((b"<!doctype html", b"<html")):
            return False

        suffix = (content_suffix or path.suffix).lower()
        if suffix and not suffix.startswith("."):
            suffix = "." + suffix

        if suffix == ".json":
            with path.open("r", encoding="utf-8-sig") as handle:
                json.load(handle)

        elif suffix == ".zip":
            with zipfile.ZipFile(path) as archive:
                bad_member = archive.testzip()
                if bad_member is not None:
                    return False

        return True

    except (OSError, UnicodeError, json.JSONDecodeError, zipfile.BadZipFile, zlib.error, lzma.LZMAError):
        return False


def recovery_partial_exists(path: Path) -> bool:
    """Return whether a recovery partial is a regular, non-symlink file."""
    try:
        mode = path.lstat().st_mode
    except FileNotFoundError:
        return False
    if not stat.S_ISREG(mode):
        raise RuntimeError(f"Unsafe recovery partial path: {path}")
    return True


def create_recovery_partial(path: Path) -> None:
    """Create a new regular recovery partial without following symlinks."""
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    flags |= getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(path, flags, 0o600)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise RuntimeError(f"Recovery partial is not a regular file: {path}")
    finally:
        os.close(fd)


def restore_known_recovery_fallback(url: str, destination: Path) -> bool:
    """Restore an exact embedded fallback for a specifically pinned support asset."""
    try:
        relative = destination.resolve().relative_to(MIRROR_ROOT.resolve()).as_posix()
    except (OSError, ValueError):
        return False

    if url == DOWNLOADER_TEST_URL and relative == DOWNLOADER_TEST_RELATIVE_PATH:
        payload = DOWNLOADER_TEST_FALLBACK_BYTES
        expected_size = DOWNLOADER_TEST_FALLBACK_SIZE
        expected_sha256 = DOWNLOADER_TEST_FALLBACK_SHA256
        content_suffix = ".txt"
        asset_name = "downloader-test.txt"

    elif url == BRISQUE_URL and relative == BRISQUE_RELATIVE_PATH:
        try:
            compressed = base64.b64decode(
                BRISQUE_FALLBACK_ZLIB_BASE64,
                validate=True,
            )
            payload = zlib.decompress(compressed)
        except (ValueError, zlib.error) as error:
            raise RuntimeError(
                f"Embedded brisque.xml fallback decoding failed: {error}"
            ) from error
        expected_size = BRISQUE_FALLBACK_SIZE
        expected_sha256 = BRISQUE_FALLBACK_SHA256
        content_suffix = ".xml"
        asset_name = "brisque.xml"

    else:
        return False

    if len(payload) != expected_size:
        raise RuntimeError(f"Embedded {asset_name} fallback size is invalid.")
    if hashlib.sha256(payload).hexdigest().upper() != expected_sha256:
        raise RuntimeError(f"Embedded {asset_name} fallback SHA-256 is invalid.")

    destination.parent.mkdir(parents=True, exist_ok=True)
    descriptor, staged_name = tempfile.mkstemp(
        prefix=f".{destination.name}.",
        suffix=".fallback",
        dir=str(destination.parent),
    )
    staged_file = Path(staged_name)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())

        if not recovery_file_is_usable(
            staged_file,
            expected_size,
            expected_sha256,
            content_suffix=content_suffix,
        ):
            raise RuntimeError(f"Embedded {asset_name} fallback failed validation.")

        os.replace(staged_file, destination)
        return True

    except BaseException:
        try:
            os.close(descriptor)
        except OSError:
            pass
        staged_file.unlink(missing_ok=True)
        raise


def recovery_download_backend() -> tuple[str, str] | None:
    """Return the supported recovery backend for the current platform."""
    if CURRENT_OS == "windows":
        curl = shutil.which("curl") or shutil.which("curl.exe")
        return ("curl", curl) if curl else None
    if CURRENT_OS in {"linux", "darwin"}:
        curl = shutil.which("curl")
        if curl:
            return ("curl", curl)
        wget = shutil.which("wget")
        if wget:
            return ("wget", wget)
        return None
    return None

def recovery_wget_resolve_url(
    wget: str, url: str, allowed_schemes: set[str],
) -> str | None:
    """Resolve wget redirects without crossing a forbidden source-scheme boundary."""
    current = url
    for _redirect in range(11):
        if urlparse(current).scheme.lower() not in allowed_schemes:
            print(f"Recovery blocked wget redirect to disallowed protocol: {current}")
            return None
        try:
            result = subprocess.run(
                [
                    wget, "--spider", "--server-response", "--max-redirect=0",
                    "--timeout=10", "--tries=1", current,
                ],
                capture_output=True, text=True, check=False,
            )
        except OSError as error:
            print(f"Recovery wget execution failed: {error}")
            return None
        if result.returncode == 0:
            return current
        output = (result.stderr or "") + "\n" + (result.stdout or "")
        locations = re.findall(
            r"^\s*Location:\s*(\S+)", output,
            flags=re.IGNORECASE | re.MULTILINE,
        )
        if not locations:
            return None
        redirected = urljoin(current, locations[-1])
        if urlparse(redirected).scheme.lower() not in allowed_schemes:
            print(f"Recovery blocked wget redirect to disallowed protocol: {redirected}")
            return None
        current = redirected
    print("Recovery wget redirect limit exceeded.")
    return None

def run_recovery_backend(
    backend: tuple[str, str], *, url: str, output: Path, resume: bool,
) -> int:
    backend_name, executable = backend
    parsed = urlparse(url)
    if backend_name == "curl":
        allowed_protocol = "=http,https" if parsed.scheme.lower() == "http" else "=https"
        command = [
            executable, "--proto", allowed_protocol, "--proto-redir", allowed_protocol,
            "--location", "--fail", "--retry", "2", "--connect-timeout", "10",
            "--speed-time", "60", "--speed-limit", "1024", "--show-error",
        ]
        if resume:
            command.extend(["-C", "-"])
        command.extend(["-o", str(output), url])
    elif backend_name == "wget":
        allowed_schemes = {"http", "https"} if parsed.scheme.lower() == "http" else {"https"}
        resolved_url = recovery_wget_resolve_url(executable, url, allowed_schemes)
        if resolved_url is None:
            return 8
        command = [
            executable, "--max-redirect=0", "--tries=2", "--timeout=60",
            "--no-verbose", "--output-document", str(output),
        ]
        if resume:
            command.append("--continue")
        command.append(resolved_url)
    else:
        raise RuntimeError(f"Unsupported recovery backend: {backend_name}")
    try:
        return subprocess.run(command, check=False).returncode
    except OSError as error:
        print(f"Recovery {backend_name} execution failed: {error}")
        return 127

def download_recovery_file(
    url: str,
    destination: Path,
    *,
    expected_size: int | None = None,
    expected_sha256: str | None = None,
    content_suffix: str | None = None,
) -> bool:
    try:
        ensure_mirror_directory(destination.parent)
    except RuntimeError as error:
        print(f"Recovery destination rejected: {error}")
        return False
    if mirror_path_has_link_component(destination):
        print(f"Recovery destination rejected: link-like path component: {destination}")
        return False
    temporary_file = destination.with_name(destination.name + ".part")
    if expected_size is None or expected_sha256 is None:
        known_size, known_sha = recovery_expected_integrity(destination)
        if expected_size is None:
            expected_size = known_size
        if expected_sha256 is None:
            expected_sha256 = known_sha
    expected_size = int(expected_size or 0)
    expected_sha256 = str(expected_sha256 or "").upper()
    backend = recovery_download_backend()
    validation_suffix = content_suffix or destination.suffix
    if backend is None:
        if CURRENT_OS == "windows":
            print("Recovery unavailable: curl was not found.")
        else:
            print("Recovery unavailable: curl and wget were not found.")
        return False

    if recovery_partial_exists(temporary_file):
        partial_size = temporary_file.stat().st_size
        if partial_size <= 0 or (expected_size > 0 and partial_size > expected_size):
            temporary_file.unlink(missing_ok=True)
        elif expected_size > 0 and partial_size == expected_size:
            if recovery_file_is_usable(
                temporary_file,
                expected_size,
                expected_sha256,
                content_suffix=validation_suffix,
            ):
                temporary_file.replace(destination)
                return True
            temporary_file.unlink(missing_ok=True)

    if recovery_partial_exists(temporary_file):
        resume_start_size = temporary_file.stat().st_size

        result_code = run_recovery_backend(
            backend, url=url, output=temporary_file, resume=True
        )
        if backend[0] == "curl" and result_code in {33, 36}:
            print("Recovery resume was rejected. Restarting from byte zero.")
            temporary_file.unlink(missing_ok=True)
        elif result_code != 0:
            return False
        else:
            if not recovery_partial_exists(temporary_file):
                return False
            resume_end_size = temporary_file.stat().st_size

            resume_incomplete = (
                expected_size <= 0 or resume_end_size < expected_size
            )
            if resume_incomplete and resume_end_size <= resume_start_size:
                print(
                    "Recovery resume made no progress. "
                    "Restarting from byte zero."
                )
                temporary_file.unlink(missing_ok=True)

    if not recovery_partial_exists(temporary_file):
        create_recovery_partial(temporary_file)
        result_code = run_recovery_backend(
            backend, url=url, output=temporary_file, resume=False
        )
        if result_code != 0:
            try:
                if temporary_file.stat().st_size <= 0:
                    temporary_file.unlink(missing_ok=True)
            except OSError:
                pass
            return False

    if not recovery_partial_exists(temporary_file):
        return False

    if not recovery_file_is_usable(
        temporary_file,
        expected_size,
        expected_sha256,
        content_suffix=validation_suffix,
    ):
        try:
            actual = temporary_file.stat().st_size
        except OSError:
            actual = 0
        if expected_size > 0 and actual > expected_size:
            temporary_file.unlink(missing_ok=True)
        return False

    if destination.is_file() and recovery_file_is_usable(
        destination,
        expected_size,
        expected_sha256,
        content_suffix=validation_suffix,
    ):
        temporary_file.unlink(missing_ok=True)
        return True

    temporary_file.replace(destination)
    return True


def recovery_candidate_path(url: str, destination: Path) -> Path:
    token = hashlib.sha256(url.encode("utf-8")).hexdigest()[:16]
    return destination.with_name(destination.name + f".candidate-{token}")


def verify_recovery_alias_candidate(url: str, destination: Path) -> bool:
    """Download a second owner independently and compare without overwriting."""
    candidate = recovery_candidate_path(url, destination)
    candidate.unlink(missing_ok=True)
    candidate.with_name(candidate.name + ".part").unlink(missing_ok=True)
    try:
        if not download_recovery_file(
            url,
            candidate,
            expected_size=0,
            expected_sha256="",
            content_suffix=destination.suffix,
        ):
            return False
        if not destination.is_file():
            return False
        return (
            candidate.stat().st_size == destination.stat().st_size
            and sha256_file(candidate) == sha256_file(destination)
        )
    finally:
        candidate.unlink(missing_ok=True)
        candidate.with_name(candidate.name + ".part").unlink(missing_ok=True)


def recover_logged_404_files() -> bool:
    urls = read_recovery_urls(ERROR_REPORT_FILE)

    print()
    print("Logged 404 recovery")
    print(f"  URLs found: {len(urls)}")
    print()

    if not urls:
        print("Recovery complete:")
        print("  Downloaded      : 0")
        print("  Already present : 0")
        print("  Aliases verified: 0")
        print("  Route rejected  : 0")
        print("  Not permitted   : 0")
        print("  Failed          : 0")
        return True

    embedded_urls = {DOWNLOADER_TEST_URL, BRISQUE_URL}
    network_recovery_urls = [url for url in urls if url not in embedded_urls]
    if network_recovery_urls and not validate_recovery_hosts(network_recovery_urls):
        return False

    recovered = 0
    already_present = 0
    aliases_verified = 0
    route_rejected = 0
    not_permitted = 0
    failed = 0

    for index, url in enumerate(urls, start=1):
        route_status = recovery_url_known_v2_route_status(url)
        destination = recovery_destination(url)

        print(f"[Recovery {index}/{len(urls)}]")
        print(f"URL : {url}")

        if route_status == "denied":
            print("Known V2 path requested through a non-owner route; recovery rejected.")
            if mark_recovery_url_rejected(ERROR_REPORT_FILE, url):
                print("Report: REPORTED-REJECTED")
                route_rejected += 1
            else:
                print("Unable to retire the rejected report entry.")
                failed += 1
            print()
            continue

        if destination is None:
            print("Skipping non-recoverable URL.")
            not_permitted += 1
            print()
            continue

        print(f"File: {destination}")
        try:
            relative = destination.resolve().relative_to(MIRROR_ROOT.resolve()).as_posix()
        except (OSError, ValueError):
            relative = ""

        known_embedded = False
        if url == DOWNLOADER_TEST_URL and relative == DOWNLOADER_TEST_RELATIVE_PATH:
            expected_size = DOWNLOADER_TEST_FALLBACK_SIZE
            expected_sha256 = DOWNLOADER_TEST_FALLBACK_SHA256
            known_embedded = True
        elif url == BRISQUE_URL and relative == BRISQUE_RELATIVE_PATH:
            expected_size = BRISQUE_FALLBACK_SIZE
            expected_sha256 = BRISQUE_FALLBACK_SHA256
            known_embedded = True
        else:
            expected_size, expected_sha256 = recovery_expected_integrity(destination)

        known_v2 = (
            not known_embedded
            and RECOVERY_V2_INTEGRITY.get(str(destination.resolve()).casefold()) is not None
        )
        trusted_record = (
            None if known_embedded or known_v2
            else trusted_discovered_record(destination)
        )

        if destination.is_file():
            if recovery_file_is_usable(
                destination,
                expected_size,
                expected_sha256,
            ):
                if known_v2 or known_embedded:
                    if known_v2:
                        print("Already exists and matches V2 size + SHA-256. Marking as fixed.")
                    else:
                        print(
                            "Embedded support asset already exists and matches "
                            "pinned size + SHA-256. Marking as fixed."
                        )
                    if mark_recovery_url_fixed(ERROR_REPORT_FILE, url):
                        print("Report: REPORTED-FIXED")
                        already_present += 1
                    else:
                        print("Report entry was not changed.")
                        failed += 1
                    print()
                    continue

                trusted_urls = (
                    recovered_asset_source_urls(trusted_record)
                    if trusted_record is not None
                    else []
                )
                normalized_url = normalized_recovered_asset_source_url(
                    url,
                    expected_relative=destination.resolve().relative_to(MIRROR_ROOT.resolve()).as_posix(),
                )
                if trusted_record is not None and normalized_url in trusted_urls:
                    print("Already exists and matches its trusted recovered baseline. Marking as fixed.")
                    if mark_recovery_url_fixed(ERROR_REPORT_FILE, url):
                        print("Report: REPORTED-FIXED")
                        already_present += 1
                    else:
                        print("Report entry was not changed.")
                        failed += 1
                    print()
                    continue

                print(
                    "Existing bytes are not yet owned by this source URL. "
                    "Downloading an isolated comparison copy."
                )
                if verify_recovery_alias_candidate(url, destination):
                    try:
                        record_recovered_server_asset(url, destination)
                    except (OSError, ValueError, RuntimeError) as error:
                        print(f"Integrity/report update failed: {error}")
                        failed += 1
                        print()
                        continue
                    if mark_recovery_url_fixed(ERROR_REPORT_FILE, url):
                        print("Alias bytes match; source ownership was added.")
                        print("Report: REPORTED-FIXED")
                        aliases_verified += 1
                    else:
                        print("Alias matched, but the report entry was not changed.")
                        failed += 1
                    print()
                    continue

                print("Destination collision: upstream bytes differ from the existing file.")
                print("Existing file was preserved and the report remains unresolved.")
                failed += 1
                print()
                continue

            if known_v2 or known_embedded or trusted_record is not None:
                actual_size = destination.stat().st_size
                actual_sha = sha256_file(destination) if actual_size > 0 else ""
                if known_v2:
                    label = "known V2 file"
                elif known_embedded:
                    label = "embedded support asset"
                else:
                    label = "discovered file"
                print(
                    f"Existing {label} failed integrity validation "
                    f"({actual_size} of {expected_size} bytes)."
                )
                if actual_size == expected_size and actual_sha != expected_sha256:
                    print("Existing file has the expected size but the wrong SHA-256.")
            else:
                print("Existing untrusted static file failed validation.")

            if known_embedded:
                print("Restoring the embedded known-good copy locally.")
            else:
                print(
                    "Downloading a validated replacement while preserving "
                    "the existing file until validation succeeds."
                )

        used_embedded_fallback = False
        if known_embedded:
            try:
                recovery_succeeded = restore_known_recovery_fallback(url, destination)
                used_embedded_fallback = recovery_succeeded
            except (OSError, ValueError, RuntimeError) as error:
                print(f"Embedded recovery fallback failed: {error}")
                recovery_succeeded = False
        else:
            recovery_succeeded = download_recovery_file(url, destination)

        if not recovery_succeeded and not known_embedded:
            try:
                used_embedded_fallback = restore_known_recovery_fallback(url, destination)
            except (OSError, ValueError, RuntimeError) as error:
                print(f"Embedded recovery fallback failed: {error}")
                used_embedded_fallback = False

            if used_embedded_fallback:
                recovery_succeeded = True
                print(
                    f"Original {destination.name} source is unavailable; "
                    "restored the embedded known-good fallback."
                )

        if recovery_succeeded:
            if used_embedded_fallback:
                print("Recovered successfully from embedded fallback.")
            else:
                print("Downloaded successfully.")
            if not known_embedded:
                try:
                    record_recovered_server_asset(url, destination)
                except (OSError, ValueError, RuntimeError) as error:
                    print(f"Integrity/report update failed: {error}")
                    failed += 1
                    print()
                    continue

            if mark_recovery_url_fixed(ERROR_REPORT_FILE, url):
                print("Report: REPORTED-FIXED")
            else:
                print("Warning: report entry was not changed.")
                print("Recovery remains unresolved for this URL.")
                failed += 1

            recovered += 1

        else:
            print("Download failed or failed integrity/content validation.")
            failed += 1

        print()

    print("Recovery complete:")
    print(f"  Downloaded      : {recovered}")
    print(f"  Already present : {already_present}")
    print(f"  Aliases verified: {aliases_verified}")
    print(f"  Route rejected  : {route_rejected}")
    print(f"  Not permitted   : {not_permitted}")
    print(f"  Failed          : {failed}")

    if not_permitted > 0:
        print()
        print(
            "Recovery remains unresolved because one or more URLs "
            "are not permitted for automatic recovery."
        )

    return failed == 0 and not_permitted == 0




def _self_test_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest().upper()


def _self_test_file_hashes(paths: list[Path]) -> dict[str, str]:
    values: dict[str, str] = {}
    for path in paths:
        if path.is_file() and not path.is_symlink():
            values[str(path)] = _self_test_sha256(path)
    return values


def _run_self_test_case(
    results: list[tuple[str, str, str]],
    label: str,
    callback,
) -> None:
    try:
        detail = callback()
        results.append((label, "PASSED", str(detail or "")))
    except Exception as error:
        results.append((label, "FAILED", str(error)))


def _self_test_manifest_database() -> str:
    index, snapshots, physical_records = validate_v2_manifest_bundle()
    manifest_entries = index.get("manifests", [])
    if len(manifest_entries) != 10:
        raise RuntimeError(f"Expected 10 snapshot manifests, found {len(manifest_entries)}.")
    if len(physical_records) != 605 or int(index.get("unique_physical_files", -1)) != 605:
        raise RuntimeError("Expected 605 unique physical files.")

    raw_snapshot = snapshots.get("RAW_MODELS.v2.json")
    if not isinstance(raw_snapshot, dict):
        raise RuntimeError("RAW_MODELS.v2.json is missing.")
    if int(raw_snapshot.get("logical_entries", -1)) != 132:
        raise RuntimeError("Expected RAW_MODELS.v2.json to contain 132 records.")

    gigapixel_snapshot = snapshots.get(GIGAPIXEL_844_V2_MANIFEST_NAME)
    if not isinstance(gigapixel_snapshot, dict):
        raise RuntimeError("Gigapixel 8.4.4 snapshot is missing.")
    if int(gigapixel_snapshot.get("logical_entries", -1)) != 87:
        raise RuntimeError("Expected Gigapixel 8.4.4 to contain 87 records.")

    # validate_v2_manifest_bundle() already verifies every pinned payload hash,
    # index/snapshot count, logical/physical total and cross-manifest integrity.
    expected_overall_logical = int(index.get("logical_entries", 0)) + len(VIDEO_AI_715_CAPTURED_PACKAGE_RECORDS)
    if download_logical_total != expected_overall_logical:
        raise RuntimeError(
            "Overall logical inventory does not match the manifest-index + supplemental records."
        )
    captured_paths = {
        str(record["relative_path"]).replace("\\", "/").casefold()
        for record in VIDEO_AI_715_CAPTURED_PACKAGE_RECORDS
    }
    if len(captured_paths) != 1:
        raise RuntimeError("Expected one supplemental Video AI package path.")
    migrated_snapshot = snapshots.get(VIDEO_AI_715_V2_MANIFEST_NAME)
    if not isinstance(migrated_snapshot, dict):
        raise RuntimeError("Video AI 7.1.5 V2 package snapshot is missing.")
    migrated_by_path = {
        str(record.get("relative_path", "")).casefold(): record
        for record in migrated_snapshot.get("files", [])
        if isinstance(record, dict)
    }
    expected_migrated_integrity = {
        "astra_support/20250415/dependencies.zip": (
            3774291280,
            "C0338E16FF230D76F3D2163AD86A8D8B8C6D74C169BF305259B33DF229E171CF",
        ),
        "astra_support/20250604/runner.zip": (
            8184029,
            "AF3C355AD1CC5E907AF1390F536336013EAB39435D82E4453219F8B148D43EAD",
        ),
    }
    for relative_path, (expected_size, expected_sha256) in expected_migrated_integrity.items():
        record = migrated_by_path.get(relative_path.casefold())
        if (
            not isinstance(record, dict)
            or int(record.get("size_bytes", -1)) != expected_size
            or str(record.get("sha256", "")).upper() != expected_sha256
        ):
            raise RuntimeError(
                "Migrated Video AI 7.1.5 V2 integrity metadata failed: " + relative_path
            )
    overall_physical = len(physical_records) + len(captured_paths)
    expected_overall_physical = len({
        str(record["relative_path"]).replace("\\", "/").casefold()
        for record in current_logical_inventory_records()
    } | set(captured_paths))
    if overall_physical != expected_overall_physical:
        raise RuntimeError(
            f"Overall physical inventory mismatch: {{overall_physical}} != {{expected_overall_physical}}."
        )
    return (
        f"{len(manifest_entries)} snapshots; {download_logical_total} logical; "
        f"{overall_physical} physical; RAW {raw_snapshot.get('logical_entries')}"
    )



def _self_test_route_ownership() -> str:
    """Exercise exact model ownership and captured API/telemetry boundaries."""
    import contextlib
    import io
    import runpy
    from email.message import Message
    from http import HTTPStatus
    from urllib.parse import urlparse

    namespace = runpy.run_path(str(SERVER_PY))
    namespace["validate_server_assets"]()
    handler_class = namespace["TopazMirrorHandler"]
    model_routes = namespace["MODEL_ROUTES"]
    canonical_paths = namespace["MODEL_CANONICAL_PATHS"]
    sharpen_alias_owners = namespace["SHARPEN_ALIAS_OWNERS"]
    probe_routes = namespace["PROBE_ASSET_ROUTES"]
    probe_canonical_paths = namespace["PROBE_ASSET_CANONICAL_PATHS"]

    expected_probe_routes = {
        ("https", "image-models.topazlabs.com", "/test.txt"): "test.txt",
        ("https", "models-r2.topazlabs.com", "/test.txt"): "test.txt",
        ("https", "models-r2.topazlabs.com", "/1.1/test.txt"): "1.1/test.txt",
        ("https", "models.topazlabs.com", "/_test/downloader-test.txt"): "_test/downloader-test.txt",
        ("https", "image-models.topazlabs.com", "/_test/models-bal-test.txt"): "_test/models-bal-test.txt",
        ("https", "models-bal.topazlabs.com", "/_test/models-bal-test.txt"): "_test/models-bal-test.txt",
    }
    if probe_routes != expected_probe_routes:
        raise RuntimeError(
            f"Unexpected probe support-asset route table: {sorted(probe_routes.items())!r}"
        )
    if len(probe_canonical_paths) != 4:
        raise RuntimeError(
            f"Expected four canonical probe support paths, found {len(probe_canonical_paths)}."
        )

    if len(model_routes) != 717:
        raise RuntimeError(f"Expected 717 exact logical model routes, found {len(model_routes)}.")
    if len(canonical_paths) != 606:
        raise RuntimeError(f"Expected 606 canonical model paths, found {len(canonical_paths)}.")

    expected_video_ai_715_urls = {
        "https://veai-models.topazlabs.com/astra_support/20250415/dependencies.zip",
        "https://veai-models.topazlabs.com/astra_support/20250415/models.zip",
        "https://veai-models.topazlabs.com/astra_support/20250604/runner.zip",
        "https://veai-models.topazlabs.com/astra_support/20250825/dependencies.zip",
        "https://veai-models.topazlabs.com/astra_support/20250825/models.zip",
        "https://veai-models.topazlabs.com/astra_support/20250825/runner.zip",
    }
    actual_video_ai_715_urls = {
        str(record["url"]) for record in VIDEO_AI_715_EXTRA_PACKAGE_RECORDS
    }
    if actual_video_ai_715_urls != expected_video_ai_715_urls:
        raise RuntimeError(
            "Video AI 7.1.5 captured package URL history is incomplete."
        )
    for record in VIDEO_AI_715_EXTRA_PACKAGE_RECORDS:
        parsed = urlparse(str(record["url"]))
        route_key = (
            parsed.scheme.lower(),
            parsed.hostname.rstrip(".").lower() if parsed.hostname else "",
            parsed.path,
        )
        if model_routes.get(route_key) != str(record["relative_path"]):
            raise RuntimeError(
                f"Video AI 7.1.5 package route is missing: {record['url']}"
            )

    resolver = object.__new__(handler_class)

    # The authority matrix deliberately includes the captured V2 model hosts
    # plus API/telemetry hosts that must never inherit model-file ownership.
    authority_matrix = (
        ("http", "models.topazlabs.com"),
        ("https", "models.topazlabs.com"),
        ("https", "image-models.topazlabs.com"),
        ("https", "models-r2.topazlabs.com"),
        ("https", "models-bal.topazlabs.com"),
        ("https", "video-models.topazlabs.com"),
        ("https", "veai-models.topazlabs.com"),
        ("https", "api.topaz-labs.net"),
        ("https", "et.topazlabs.com"),
    )

    authorized = 0
    denied = 0
    case_denied = 0

    # Suppress the intentionally informational Sharpen alias log while the
    # route resolver is exercised directly.
    with contextlib.redirect_stdout(io.StringIO()):
        for (scheme, host, path), relative_path in model_routes.items():
            resolved = handler_class.resolve_owned_model_request(
                resolver,
                scheme,
                host,
                path,
            )
            if not isinstance(resolved, Path):
                raise RuntimeError(
                    "Authorized model route was denied: "
                    f"{scheme}://{host}{path}"
                )
            expected_parts = PurePosixPath(relative_path).parts
            if tuple(resolved.parts[-len(expected_parts):]) != expected_parts:
                raise RuntimeError(
                    "Authorized model route resolved to the wrong mirror path: "
                    f"{scheme}://{host}{path}"
                )
            authorized += 1

        for canonical_path in canonical_paths.values():
            for scheme, host in authority_matrix:
                expected_owner = (scheme, host, canonical_path) in model_routes
                resolved = handler_class.resolve_owned_model_request(
                    resolver,
                    scheme,
                    host,
                    canonical_path,
                )
                if expected_owner:
                    if not isinstance(resolved, Path):
                        raise RuntimeError(
                            "Authorized authority/path combination was denied: "
                            f"{scheme}://{host}{canonical_path}"
                        )
                else:
                    if resolved is not False:
                        raise RuntimeError(
                            "Non-owner authority inherited a model path: "
                            f"{scheme}://{host}{canonical_path}"
                        )
                    denied += 1

        # Case changes must not bypass exact route ownership on case-insensitive
        # filesystems such as normal Windows NTFS installations.
        for scheme, host, path in model_routes:
            characters = list(path)
            for index, character in enumerate(characters):
                if character.isalpha():
                    characters[index] = (
                        character.upper() if character.islower() else character.lower()
                    )
                    break
            alternate_case = "".join(characters)
            if alternate_case == path:
                raise RuntimeError(f"Unable to create case variant for model route: {path}")
            resolved = handler_class.resolve_owned_model_request(
                resolver,
                scheme,
                host,
                alternate_case,
            )
            if resolved is not False:
                raise RuntimeError(
                    "Alternate-case model route bypassed ownership: "
                    f"{scheme}://{host}{alternate_case}"
                )
            case_denied += 1

    if authorized != 717:
        raise RuntimeError(f"Expected 717 authorized route checks, got {authorized}.")
    if denied != 4737:
        raise RuntimeError(f"Expected 4737 denied non-owner checks, got {denied}.")
    if case_denied != 717:
        raise RuntimeError(f"Expected 717 denied case variants, got {case_denied}.")

    # Validate per-snapshot application authority rather than deriving it from
    # the generated route table alone. This catches accidental reassignment of
    # an entire application snapshot to another model host.
    _, snapshots, _ = validate_v2_manifest_bundle()
    expected_snapshot_authorities = {
        "GIGAPIXEL_1.3.1_captured.v2.json": {("https", "image-models.topazlabs.com")},
        GIGAPIXEL_844_V2_MANIFEST_NAME: {("https", "models.topazlabs.com")},
        "PHOTO_1.6.1_captured.v2.json": {("https", "image-models.topazlabs.com")},
        "PHOTO_AI_4.0.1_captured.v2.json": {("https", "models-bal.topazlabs.com")},
        "RAW_MODELS.v2.json": {("http", "models.topazlabs.com")},
        SHARPEN_SHA256_MANIFEST_NAME: {("https", "veai-models.topazlabs.com")},
        "STARLIGHT_2.5.v2.json": {("https", "video-models.topazlabs.com")},
        "VIDEO_1.6.1_EXTRA_PACKAGES.v2.json": {("https", "video-models.topazlabs.com")},
        "VIDEO_1.6.1_captured.v2.json": {("https", "video-models.topazlabs.com")},
        "VIDEO_AI_7.1.5_EXTRA_PACKAGES.v2.json": {("https", "veai-models.topazlabs.com")},
    }
    for filename, expected_authorities in expected_snapshot_authorities.items():
        snapshot = snapshots.get(filename)
        if not isinstance(snapshot, dict):
            raise RuntimeError(f"Route-ownership snapshot is missing: {filename}")
        observed = set()
        for record in snapshot.get("files", []):
            parsed = urlparse(str(record.get("url", "")))
            if not parsed.scheme or not parsed.hostname:
                raise RuntimeError(f"Invalid route-ownership URL in {filename}.")
            observed.add((parsed.scheme.lower(), parsed.hostname.rstrip(".").lower()))
        if observed != expected_authorities:
            raise RuntimeError(
                f"Unexpected application authority in {filename}: "
                f"expected {sorted(expected_authorities)!r}, got {sorted(observed)!r}"
            )

    # A RAW record is a residual/unattributed record. Once the same
    # models.topazlabs.com path is attributed to Gigapixel 8.4.4, it must no
    # longer remain in RAW; protocol is deliberately ignored for this
    # attribution check.
    raw_snapshot = snapshots["RAW_MODELS.v2.json"]
    gigapixel_snapshot = snapshots[GIGAPIXEL_844_V2_MANIFEST_NAME]

    def model_host_paths(snapshot: dict) -> set[tuple[str, str]]:
        values: set[tuple[str, str]] = set()
        for record in snapshot.get("files", []):
            parsed = urlparse(str(record.get("url", "")))
            host = parsed.hostname.rstrip(".").lower() if parsed.hostname else ""
            values.add((host, parsed.path))
        return values

    overlap = model_host_paths(raw_snapshot) & model_host_paths(gigapixel_snapshot)
    if overlap:
        sample = sorted(overlap)[0]
        raise RuntimeError(
            "RAW still contains a Gigapixel 8.4.4-attributed host/path: "
            f"{sample[0]}{sample[1]}"
        )

    class RoutingHandler(handler_class):
        """No-network request harness for API/application ownership tests."""

        def __init__(self, scheme: str, host: str, path: str, method: str = "GET"):
            self._self_test_scheme = scheme
            self.command = method
            self.path = path
            self.headers = Message()
            self.headers["Host"] = host
            self.wfile = io.BytesIO()
            self.status = None
            self.response_headers = {}
            self.client_address = ("127.0.0.1", 1)
            self.requestline = "SELFTEST"
            self.request_version = "HTTP/1.1"
            self._pending_request_log_lines = []
            self._result_url = None

        def request_scheme(self) -> str:
            return self._self_test_scheme

        def _request_is_https(self) -> bool:
            return self._self_test_scheme == "https"

        def current_timestamp(self) -> str:
            return "SELFTEST"

        def begin_request_log(self, *args, **kwargs) -> None:
            self._pending_request_log_lines = []

        def build_request_log_lines(self, *args, **kwargs):
            return []

        def send_response(self, code, message=None) -> None:
            self.status = int(code)

        def send_header(self, keyword, value) -> None:
            self.response_headers[str(keyword)] = str(value)

        def end_headers(self) -> None:
            return None

        def send_error(self, code, message=None, *args, **kwargs) -> None:
            self.status = int(code)

        def send_json_file(
            self,
            source: Path,
            status: HTTPStatus = HTTPStatus.OK,
            missing_message: str = "JSON response not found",
            extra_headers=(),
        ) -> None:
            self.status = int(status)

        def send_json(
            self,
            text: bytes,
            status: HTTPStatus = HTTPStatus.OK,
            extra_headers=(),
        ) -> None:
            self.status = int(status)

        def read_validated_post_body(self):
            return b"{}"

        def send_owned_model_file(self, source: Path) -> None:
            self.status = int(HTTPStatus.OK)

    def exercise(
        scheme: str,
        host: str,
        path: str,
        method: str = "GET",
    ) -> int:
        handler = RoutingHandler(scheme, host, path, method)
        if method == "POST":
            handler.do_POST()
        else:
            handler.handle_read_request()
        if handler.status is None:
            raise RuntimeError(f"Route self-test produced no HTTP status: {host}{path}")
        return int(handler.status)

    # Four deterministic probe/support paths are exact scheme+host+path routes.
    # Validate the fully initialized Server Assets state used in production, not
    # merely the empty runpy defaults. Authorized aliases remain available while
    # wrong hosts, HTTP downgrades, and alternate-case paths all return 404.
    probe_authorized = 0
    probe_denied = 0
    probe_hosts = {
        "models.topazlabs.com",
        "image-models.topazlabs.com",
        "models-r2.topazlabs.com",
        "models-bal.topazlabs.com",
        "video-models.topazlabs.com",
        "veai-models.topazlabs.com",
        "api.topaz-labs.net",
        "et.topazlabs.com",
        "evil.invalid",
    }
    for (scheme, host, path), relative_path in sorted(probe_routes.items()):
        if exercise(scheme, host, path) != 200:
            raise RuntimeError(
                f"Authorized probe support route failed: {scheme}://{host}{path}"
            )
        probe_authorized += 1

        if exercise("http", host, path) != 404:
            raise RuntimeError(
                f"Probe support route accepted wrong scheme: http://{host}{path}"
            )
        probe_denied += 1

        for wrong_host in sorted(probe_hosts - {host}):
            if (scheme, wrong_host, path) in probe_routes:
                continue
            if exercise(scheme, wrong_host, path) != 404:
                raise RuntimeError(
                    f"Wrong host inherited probe support route: {scheme}://{wrong_host}{path}"
                )
            probe_denied += 1

    for canonical_path in probe_canonical_paths.values():
        characters = list(canonical_path)
        for index, character in enumerate(characters):
            if character.isalpha():
                characters[index] = (
                    character.upper() if character.islower() else character.lower()
                )
                break
        alternate_case = "".join(characters)
        if alternate_case == canonical_path:
            raise RuntimeError(
                f"Unable to create probe support case variant: {canonical_path}"
            )
        for scheme, host, path in probe_routes:
            if path != canonical_path:
                continue
            if exercise(scheme, host, alternate_case) != 404:
                raise RuntimeError(
                    "Alternate-case probe support path bypassed ownership: "
                    f"{scheme}://{host}{alternate_case}"
                )
            probe_denied += 1

    if probe_authorized != 6:
        raise RuntimeError(
            f"Expected six authorized probe route checks, got {probe_authorized}."
        )
    if probe_denied != 56:
        raise RuntimeError(
            f"Expected 56 denied probe route checks, got {probe_denied}."
        )

    # API/application routes are host-owned, but intentionally not scheme-locked.
    api_cases = (
        ("api.topaz-labs.net", "/v2/app_state/unauthed", 200),
        ("api.topaz-labs.net", "/v2/app_state/", 200),
        ("topazlabs.com", "/api/v1/ownership/", 401),
        ("api.topaz-labs.net", "/v1/config/", 200),
    )
    for host, path, expected_status in api_cases:
        for scheme in ("http", "https"):
            status = exercise(scheme, host, path)
            if status != expected_status:
                raise RuntimeError(
                    f"Captured API owner failed: {scheme}://{host}{path} -> {status}"
                )
        wrong_host = "models.topazlabs.com" if host != "models.topazlabs.com" else "api.topaz-labs.net"
        if exercise("https", wrong_host, path) != 404:
            raise RuntimeError(f"Wrong API host inherited captured route: {wrong_host}{path}")

    # All 15 captured Plutus product IDs belong to api.topaz-labs.net.
    product_ids = (
        "1464951",
        "4973578",
        "4400087",
        *CAPTURED_PRODUCT_IDS,
    )
    if len(set(product_ids)) != 15:
        raise RuntimeError("Expected 15 unique captured Plutus product IDs.")
    for product_id in product_ids:
        path = f"/v3/plutus/product/{product_id}"
        for scheme in ("http", "https"):
            if exercise(scheme, "api.topaz-labs.net", path) != 200:
                raise RuntimeError(f"Captured Plutus product owner failed: {product_id}")
        if exercise("https", "models.topazlabs.com", path) != 404:
            raise RuntimeError(f"Wrong host inherited Plutus product route: {product_id}")
    if exercise("https", "api.topaz-labs.net", "/v3/plutus/product/9999999") != 404:
        raise RuntimeError("Unknown Plutus product escaped the reserved API namespace.")

    # Windows alternate-case / 8.3-short-name-style bypasses remain closed.
    bypass_cases = (
        ("api.topaz-labs.net", "/V2/APP_STATE/"),
        ("api.topaz-labs.net", "/v2/APP_ST~1/SHARPEN_4.1.0.json"),
        ("topazlabs.com", "/API/V1/OWNERSHIP/"),
        ("topazlabs.com", "/api/v1/OWNERS~1/unauthorized.json"),
    )
    for host, path in bypass_cases:
        if exercise("https", host, path) != 404:
            raise RuntimeError(f"API namespace bypass became reachable: {host}{path}")

    # Telemetry is host+method-owned but intentionally works over either local
    # HTTP or HTTPS endpoint when the correct captured host is used.
    for path in ("/v1/track", "/event"):
        for scheme in ("http", "https"):
            if exercise(scheme, "et.topazlabs.com", path, "POST") != 200:
                raise RuntimeError(f"Captured telemetry owner failed: {scheme} {path}")
        if exercise("https", "models.topazlabs.com", path, "POST") != 404:
            raise RuntimeError(f"Wrong host inherited telemetry endpoint: {path}")
    if exercise("https", "et.topazlabs.com", "/v1/track", "GET") != 404:
        raise RuntimeError("GET unexpectedly inherited POST-only telemetry /v1/track.")

    # Host values are case-normalized, but an explicit port must match the
    # local HTTP/HTTPS endpoint.
    normalized = RoutingHandler("https", "API.TOPAZ-LABS.NET", "/").validated_request_host()
    if normalized != "api.topaz-labs.net":
        raise RuntimeError("Host-name case normalization failed.")
    normalized = RoutingHandler("https", "api.topaz-labs.net:443", "/").validated_request_host()
    if normalized != "api.topaz-labs.net":
        raise RuntimeError("Explicit HTTPS Host port validation failed.")
    try:
        RoutingHandler("https", "api.topaz-labs.net:80", "/").validated_request_host()
    except ValueError:
        pass
    else:
        raise RuntimeError("Mismatched HTTP/HTTPS Host port was accepted.")

    # Sharpen may vary the UUID directory, but only a filename captured for the
    # correct scheme/host may use that alias behavior.
    if not sharpen_alias_owners:
        raise RuntimeError("Sharpen alias ownership table is empty.")
    sharpen_scheme, sharpen_host, sharpen_filename = sorted(sharpen_alias_owners)[0]
    sharpen_path = f"/v2/JSON_SHARPEN/12345678-1234-1234-1234-123456789abc/{sharpen_filename}"
    resolver_globals = handler_class.resolve_owned_model_request.__globals__
    saved_sharpen_resolver = resolver_globals["resolve_sharpen_model"]
    saved_repeater_mirror_root = resolver_globals["MIRROR_ROOT"]
    try:
        with tempfile.TemporaryDirectory(prefix="topaz-sharpen-route-selftest-") as temp_name:
            temporary_mirror = Path(temp_name).resolve()
            temporary_model = (
                temporary_mirror
                / "v2"
                / "JSON_SHARPEN"
                / "self-test-owner"
                / sharpen_filename
            )
            temporary_model.parent.mkdir(parents=True, exist_ok=True)
            temporary_model.write_bytes(b"route-ownership-self-test")
            resolver_globals["MIRROR_ROOT"] = temporary_mirror
            resolver_globals["resolve_sharpen_model"] = (
                lambda filename: temporary_model if filename == sharpen_filename else None
            )

            with contextlib.redirect_stdout(io.StringIO()):
                resolved = handler_class.resolve_owned_model_request(
                    resolver,
                    sharpen_scheme,
                    sharpen_host,
                    sharpen_path,
                )
                if resolved != temporary_model:
                    raise RuntimeError("Sharpen UUID alias failed for its captured owner.")
                if handler_class.resolve_owned_model_request(
                    resolver,
                    sharpen_scheme,
                    "models.topazlabs.com",
                    sharpen_path,
                ) is not False:
                    raise RuntimeError("Wrong host inherited Sharpen UUID alias ownership.")
                wrong_scheme = "http" if sharpen_scheme == "https" else "https"
                if handler_class.resolve_owned_model_request(
                    resolver,
                    wrong_scheme,
                    sharpen_host,
                    sharpen_path,
                ) is not False:
                    raise RuntimeError("Wrong scheme inherited Sharpen UUID alias ownership.")
    finally:
        resolver_globals["resolve_sharpen_model"] = saved_sharpen_resolver
        resolver_globals["MIRROR_ROOT"] = saved_repeater_mirror_root

    # Exercise the real Sharpen alias resolver through a lexical final symlink.
    # The alias route must preserve that lexical path until the descriptor-safe
    # opener rejects it; resolving the symlink first would erase the evidence.
    saved_alias_globals = {
        "MIRROR_ROOT": resolver_globals["MIRROR_ROOT"],
        "SHARPEN_JSON_ROOT": resolver_globals["SHARPEN_JSON_ROOT"],
    }
    try:
        with tempfile.TemporaryDirectory(prefix="topaz-sharpen-link-selftest-") as temp_name:
            alias_mirror = Path(temp_name).resolve() / "Mirror"
            alias_root = alias_mirror / "v2" / "JSON_SHARPEN"
            alias_link = alias_root / "linked-owner" / sharpen_filename
            alias_target = alias_root / "real-owner" / (sharpen_filename + ".target")
            alias_link.parent.mkdir(parents=True, exist_ok=True)
            alias_target.parent.mkdir(parents=True, exist_ok=True)
            alias_target.write_bytes(b"sharpen-link-target")
            resolver_globals["MIRROR_ROOT"] = alias_mirror
            resolver_globals["SHARPEN_JSON_ROOT"] = alias_root
            link_created = False
            try:
                alias_link.symlink_to(alias_target)
                link_created = True
            except OSError as error:
                if not (
                    os.name == "nt"
                    and getattr(error, "winerror", None) == 1314
                ):
                    raise
            if link_created:
                with contextlib.redirect_stdout(io.StringIO()):
                    alias_candidate = handler_class.resolve_owned_model_request(
                        resolver,
                        sharpen_scheme,
                        sharpen_host,
                        sharpen_path,
                    )
                if alias_candidate != alias_link:
                    raise RuntimeError(
                        "Sharpen alias resolution did not preserve the lexical link path."
                    )
                alias_handler = object.__new__(handler_class)
                alias_statuses: list[int] = []
                alias_handler.send_error = (
                    lambda code, *_args, **_kwargs: alias_statuses.append(int(code))
                )
                if handler_class._open_owned_model_file(
                    alias_handler, alias_candidate
                ) is not None or alias_statuses != [HTTPStatus.FORBIDDEN]:
                    raise RuntimeError(
                        "Sharpen alias link path was not rejected by the safe opener."
                    )
                translated = handler_class.translate_path(alias_handler, sharpen_path)
                if Path(translated).name != "__blocked_request__":
                    raise RuntimeError(
                        "Legacy Sharpen translate_path did not reject the link alias."
                    )
    finally:
        resolver_globals.update(saved_alias_globals)

    # Multiple Sharpen candidates may be resolved only from complete evidence.
    # One unreadable/non-regular candidate makes the filename ambiguous rather
    # than allowing the first otherwise-valid candidate to win by fallback.
    saved_candidate_globals = {
        "MIRROR_ROOT": resolver_globals["MIRROR_ROOT"],
        "SHARPEN_JSON_ROOT": resolver_globals["SHARPEN_JSON_ROOT"],
    }
    try:
        with tempfile.TemporaryDirectory(prefix="topaz-sharpen-candidate-selftest-") as temp_name:
            candidate_mirror = Path(temp_name).resolve() / "Mirror"
            candidate_root = candidate_mirror / "v2" / "JSON_SHARPEN"
            resolver_globals["MIRROR_ROOT"] = candidate_mirror
            resolver_globals["SHARPEN_JSON_ROOT"] = candidate_root
            resolve_candidate = resolver_globals["resolve_sharpen_model"]

            def candidate_path(owner: str) -> Path:
                return candidate_root / owner / sharpen_filename

            first = candidate_path("owner-a")
            second = candidate_path("owner-b")
            first.parent.mkdir(parents=True, exist_ok=True)
            second.parent.mkdir(parents=True, exist_ok=True)

            first.write_bytes(b"identical-sharpen")
            second.write_bytes(b"identical-sharpen")
            if resolve_candidate(sharpen_filename) not in {first, second}:
                raise RuntimeError("Identical Sharpen candidates were not resolved.")

            second.write_bytes(b"different-size")
            if resolve_candidate(sharpen_filename) is not None:
                raise RuntimeError("Different-size Sharpen candidates were not rejected.")

            first.write_bytes(b"AAAA")
            second.write_bytes(b"BBBB")
            if resolve_candidate(sharpen_filename) is not None:
                raise RuntimeError("Different-hash Sharpen candidates were not rejected.")

            second.unlink()
            second.mkdir()
            if resolve_candidate(sharpen_filename) is not None:
                raise RuntimeError(
                    "Unvalidatable multiple Sharpen candidates did not fail closed."
                )
    finally:
        resolver_globals.update(saved_candidate_globals)

    # BRISQUE is embedded for offline reconstruction but its V2 record still
    # owns the runtime model route. It must not leak through another host.
    brisque_path = "/" + BRISQUE_RELATIVE_PATH
    if not isinstance(
        handler_class.resolve_owned_model_request(
            resolver,
            "https",
            "models.topazlabs.com",
            brisque_path,
        ),
        Path,
    ):
        raise RuntimeError("BRISQUE V2 owner route failed.")
    if handler_class.resolve_owned_model_request(
        resolver,
        "https",
        "image-models.topazlabs.com",
        brisque_path,
    ) is not False:
        raise RuntimeError("BRISQUE leaked through a non-owner model host.")

    return (
        "717 exact owners; 4737 non-owner denials; 717 case denials; "
        "10 snapshot authorities; 4 probe paths / 6 exact owners; "
        "Video AI 7.1.5 packages 6/6 retained; "
        "RAW/Gigapixel clean; API/telemetry/Sharpen/BRISQUE pass"
    )

def _self_test_http_behavior() -> str:
    import io
    import runpy
    from email.message import Message

    namespace = runpy.run_path(str(SERVER_PY))
    handler_class = namespace["TopazMirrorHandler"]
    server_globals = handler_class.send_owned_model_file.__globals__

    with tempfile.TemporaryDirectory(prefix="topaz-http-selftest-") as temp_name:
        temporary_root = Path(temp_name).resolve()
        test_file = temporary_root / "range-test.bin"
        payload = b"0123456789abcdef"
        test_file.write_bytes(payload)
        server_globals["MIRROR_ROOT"] = temporary_root

        class DummyHandler(handler_class):
            def __init__(self, command: str, range_value: str | None = None):
                self.command = command
                self.headers = Message()
                if range_value is not None:
                    self.headers["Range"] = range_value
                self.wfile = io.BytesIO()
                self.status = None
                self.response_headers = {}
                self.client_address = ("127.0.0.1", 0)
                self.requestline = "SELFTEST"
                self.request_version = "HTTP/1.1"

            def send_response(self, code, message=None):
                self.status = int(code)

            def send_header(self, keyword, value):
                self.response_headers[str(keyword)] = str(value)

            def end_headers(self):
                return None

        def exercise(command: str, range_value: str | None = None):
            handler = DummyHandler(command, range_value)
            handler.send_owned_model_file(test_file)
            return handler

        normal_get = exercise("GET")
        if normal_get.status != 200 or normal_get.wfile.getvalue() != payload:
            raise RuntimeError("Normal GET did not return the complete file with 200.")

        normal_head = exercise("HEAD")
        if normal_head.status != 200 or normal_head.wfile.getvalue() != b"":
            raise RuntimeError("HEAD did not return 200 with an empty body.")
        if normal_head.response_headers.get("Content-Length") != str(len(payload)):
            raise RuntimeError("HEAD Content-Length is incorrect.")

        expected_ranges = {
            "bytes=2-5": (b"2345", "bytes 2-5/16"),
            "bytes=10-": (b"abcdef", "bytes 10-15/16"),
            "bytes=-4": (b"cdef", "bytes 12-15/16"),
        }
        for range_value, (expected_body, expected_content_range) in expected_ranges.items():
            handler = exercise("GET", range_value)
            if handler.status != 206 or handler.wfile.getvalue() != expected_body:
                raise RuntimeError(f"Range request failed: {range_value}")
            if handler.response_headers.get("Content-Range") != expected_content_range:
                raise RuntimeError(f"Content-Range failed: {range_value}")

        head_range = exercise("HEAD", "bytes=2-5")
        if head_range.status != 206 or head_range.wfile.getvalue() != b"":
            raise RuntimeError("HEAD Range did not return 206 with an empty body.")

        invalid_range = exercise("GET", "bytes=99-100")
        if invalid_range.status != 416:
            raise RuntimeError("Unsatisfiable Range did not return 416.")
        if invalid_range.response_headers.get("Content-Range") != "bytes */16":
            raise RuntimeError("416 Content-Range is incorrect.")

    server_class = namespace["LoggingHTTPSServer"]
    server_method_globals = server_class.process_request_thread.__globals__

    class _SelfTestRawSocket:
        def __init__(self):
            self.timeouts = []
            self.closed = False

        def settimeout(self, value):
            self.timeouts.append(value)

        def close(self):
            self.closed = True

    class _SelfTestTLSSocket(_SelfTestRawSocket):
        def __init__(self, handshake_error=None):
            super().__init__()
            self.handshake_error = handshake_error

        def do_handshake(self):
            if self.handshake_error is not None:
                raise self.handshake_error

    class _SelfTestSSLContext:
        def __init__(self, tls_socket):
            self.tls_socket = tls_socket

        def wrap_socket(self, raw_socket, **_kwargs):
            self.raw_socket = raw_socket
            return self.tls_socket

    # Force a non-OSError handler failure. ThreadingMixIn must catch it,
    # call handle_error(), run shutdown_request(), and leave no exception.
    raw_socket = _SelfTestRawSocket()
    tls_socket = _SelfTestTLSSocket()
    server = server_class.__new__(server_class)
    server.ssl_context = _SelfTestSSLContext(tls_socket)
    worker_events = []

    def _raise_handler_failure(_request, _client_address):
        raise RuntimeError("forced handler failure")

    server.finish_request = _raise_handler_failure
    server.handle_error = lambda _request, _client: worker_events.append(
        ("handle_error", type(sys.exc_info()[1]).__name__)
    )
    server.shutdown_request = lambda request: (
        worker_events.append(("shutdown", None)),
        request.close(),
    )
    server.process_request_thread(raw_socket, ("127.0.0.1", 44300))
    if raw_socket.timeouts != [namespace["TLS_HANDSHAKE_TIMEOUT_SECONDS"]]:
        raise RuntimeError("HTTPS raw-socket handshake timeout was not restored.")
    if tls_socket.timeouts != [
        namespace["TLS_HANDSHAKE_TIMEOUT_SECONDS"],
        namespace["HTTP_CLIENT_TIMEOUT_SECONDS"],
    ]:
        raise RuntimeError("HTTPS post-handshake client timeout was not restored.")
    if worker_events != [("handle_error", "RuntimeError"), ("shutdown", None)]:
        raise RuntimeError("HTTPS handler exception did not use ThreadingMixIn cleanup.")
    if not tls_socket.closed:
        raise RuntimeError("HTTPS handler-failure socket was not closed.")

    # Force a generic handshake SSLError. It must be sanitized/reported without
    # escaping as a traceback and its SNI state/socket must be cleaned up.
    raw_socket = _SelfTestRawSocket()
    tls_socket = _SelfTestTLSSocket(ssl.SSLError("forced handshake failure"))
    server = server_class.__new__(server_class)
    server.ssl_context = _SelfTestSSLContext(tls_socket)
    emitted_blocks = []
    reported_blocks = []
    saved_emit = server_method_globals["emit_log_block"]
    saved_append = server_method_globals["append_error_report"]
    server_method_globals["emit_log_block"] = lambda lines: emitted_blocks.append(list(lines))
    server_method_globals["append_error_report"] = lambda value: reported_blocks.append(value)
    server_method_globals["TLS_SNI"][tls_socket] = "selftest.topazlabs.com"
    try:
        server.process_request_thread(raw_socket, ("127.0.0.1", 44301))
    finally:
        server_method_globals["emit_log_block"] = saved_emit
        server_method_globals["append_error_report"] = saved_append
    if not emitted_blocks or not reported_blocks:
        raise RuntimeError("Generic TLS handshake failure was not controlled/reported.")
    if "TLS / SSL Handshake Failure" not in reported_blocks[0]:
        raise RuntimeError("TLS handshake report lost its controlled diagnostic section.")
    if tls_socket in server_method_globals["TLS_SNI"] or not tls_socket.closed:
        raise RuntimeError("TLS handshake failure did not clean SNI/socket state.")

    return (
        "GET/HEAD 200; Range 206; invalid Range 416; "
        "HTTPS timeout/handler isolation/handshake reporting pass"
    )


def _self_test_recovery() -> str:
    global MIRROR_ROOT
    import runpy

    downloader = runpy.run_path(str(OUT_PORTABLE_DOWNLOADER))
    downloader_globals = downloader["download_file"].__globals__

    with tempfile.TemporaryDirectory(prefix="topaz-recovery-selftest-") as temp_name:
        mirror = (Path(temp_name) / "Mirror").resolve()
        mirror.mkdir(parents=True)
        downloader_globals["MIRROR_ROOT"] = mirror
        downloader_globals["mirror_resolved"] = mirror
        downloader_report = Path(temp_name) / "Topaz_Offline_Download_Creator_Error.txt"
        downloader_globals["ERROR_REPORT"] = downloader_report

        correct = b"REPAIR-OK"
        bad = b"REPAIR-NO"
        expected_sha = hashlib.sha256(correct).hexdigest().upper()
        url = "https://models.topazlabs.com/v1/self-test.bin"

        curl_calls = []
        def install_fake_downloader(payload: bytes, *, assert_old: bytes | None = None):
            def fake_run_curl(command):
                curl_calls.append(list(command))
                if "-o" not in command:
                    raise RuntimeError("Self-test fake curl expected -o output.")
                output = Path(command[command.index("-o") + 1])
                if assert_old is not None:
                    destination = output.with_name(output.name.removesuffix(".part"))
                    if destination.read_bytes() != assert_old:
                        raise RuntimeError("Existing destination changed before staged promotion.")
                output.write_bytes(payload)
                return 0
            downloader_globals["run_curl"] = fake_run_curl

        downloader_globals["report_hosts_download_block"] = lambda _url: False

        # Genuine attempted failure: it must be written to the shared error report.
        failed_url = "https://models.topazlabs.com/v1/self-test-failed.bin"
        failed_destination = mirror / "v1" / "self-test-failed.bin"
        def failed_run_curl(command):
            curl_calls.append(list(command))
            return 22
        downloader_globals["run_curl"] = failed_run_curl
        if downloader["download_file"](
            ("curl", "curl"), url=failed_url, destination=failed_destination, expected_size=len(correct)
        ):
            raise RuntimeError("Failed-download reporting self-test unexpectedly succeeded.")
        report_text = downloader_report.read_text(encoding="utf-8")
        if f"URL : {failed_url}" not in report_text:
            raise RuntimeError("Failed Downloader request was not written to the error report.")
        install_fake_downloader(correct)
        if not downloader["download_file"](
            ("curl", "curl"), url=failed_url, destination=failed_destination, expected_size=len(correct)
        ):
            raise RuntimeError("Failed-download retry self-test did not recover.")
        report_text = downloader_report.read_text(encoding="utf-8")
        if f"REPORTED-FIXED : {failed_url}" not in report_text:
            raise RuntimeError("Successful Downloader retry did not mark the report fixed.")

        # Missing file: stage and promote a complete file.
        destination = mirror / "v1" / "missing.bin"
        install_fake_downloader(correct)
        if not downloader["download_file"](
            ("curl", "curl"), url=url, destination=destination, expected_size=len(correct)
        ):
            raise RuntimeError("Missing-file download self-test failed.")
        if destination.read_bytes() != correct or destination.with_name(destination.name + ".part").exists():
            raise RuntimeError("Missing-file staging/promotion self-test failed.")

        # Wrong-size destination: preserve it until a verified replacement is ready.
        destination = mirror / "v1" / "wrong-size.bin"
        destination.write_bytes(b"OLD")
        install_fake_downloader(correct, assert_old=b"OLD")
        if not downloader["download_file"](
            ("curl", "curl"), url=url, destination=destination, expected_size=len(correct),
            force_repair=True, expected_sha256=expected_sha,
        ):
            raise RuntimeError("Wrong-size repair self-test failed.")
        if destination.read_bytes() != correct:
            raise RuntimeError("Wrong-size repair did not promote verified bytes.")

        # Same-size bad SHA: reject staged replacement and preserve old destination.
        destination = mirror / "v1" / "wrong-sha.bin"
        old_bytes = b"KEEP-OLD!"
        if len(old_bytes) != len(correct) or len(bad) != len(correct):
            raise RuntimeError("Self-test repair payload lengths are inconsistent.")
        destination.write_bytes(old_bytes)
        install_fake_downloader(bad, assert_old=old_bytes)
        import contextlib
        import io
        with contextlib.redirect_stdout(io.StringIO()):
            bad_sha_accepted = downloader["download_file"](
                ("curl", "curl"), url=url, destination=destination, expected_size=len(correct),
                force_repair=True, expected_sha256=expected_sha,
            )
        if bad_sha_accepted:
            raise RuntimeError("Bad same-size SHA replacement was accepted.")
        if destination.read_bytes() != old_bytes:
            raise RuntimeError("Failed SHA repair replaced the existing destination.")
        if destination.with_name(destination.name + ".part").exists():
            raise RuntimeError("Rejected SHA repair left a full-size partial behind.")

        # Hosts feedback guard: curl must not run or mutate the destination.
        destination = mirror / "v1" / "hosts-guard.bin"
        destination.write_bytes(old_bytes)
        before_calls = len(curl_calls)
        downloader_globals["report_hosts_download_block"] = lambda _url: True
        if downloader["download_file"](
            ("curl", "curl"), url=url, destination=destination, expected_size=len(correct),
            force_repair=True, expected_sha256=expected_sha,
        ):
            raise RuntimeError("Hosts feedback guard unexpectedly allowed a download.")
        if len(curl_calls) != before_calls or destination.read_bytes() != old_bytes:
            raise RuntimeError("Hosts feedback guard allowed curl or destination mutation.")

        # Recovery report transition is atomic and preserves unrelated text.
        report = Path(temp_name) / "Topaz_Offline_Download_Creator_Error.txt"
        report.write_text(
            "Before\nURL : https://models.topazlabs.com/v1/future.xml\nAfter\n",
            encoding="utf-8",
            newline="\n",
        )
        if not mark_recovery_url_fixed(
            report,
            "https://models.topazlabs.com/v1/future.xml",
        ):
            raise RuntimeError("URL -> REPORTED-FIXED transition failed.")
        report_text = report.read_text(encoding="utf-8")
        if "REPORTED-FIXED : https://models.topazlabs.com/v1/future.xml" not in report_text:
            raise RuntimeError("Recovery report did not retain the fixed marker.")
        if "Before" not in report_text or "After" not in report_text:
            raise RuntimeError("Recovery report update damaged unrelated lines.")

    unknown_support = recovery_destination(
        "https://models.topazlabs.com/v1/self-test-future.xml"
    )
    if unknown_support is None:
        raise RuntimeError("Unknown permitted XML support recovery was rejected.")
    if recovery_destination("https://models.topazlabs.com/v1/track") is not None:
        raise RuntimeError("Blocked API route was accepted for static recovery.")

    if os.name != "nt":
        saved_creator_mirror = MIRROR_ROOT
        try:
            with tempfile.TemporaryDirectory(prefix="topaz-creator-link-recovery-selftest-") as temp_name:
                MIRROR_ROOT = Path(temp_name).resolve() / "Mirror"
                real_parent = MIRROR_ROOT / "real"
                real_parent.mkdir(parents=True)
                linked_parent = MIRROR_ROOT / "linked"
                linked_parent.symlink_to(real_parent, target_is_directory=True)
                linked_url = "https://models.topazlabs.com/linked/future-model.tz3"
                if recovery_destination(linked_url) is not None:
                    raise RuntimeError(
                        "Creator recovery accepted a link-like Mirror parent."
                    )
                if download_recovery_file(
                    linked_url, linked_parent / "future-model.tz3",
                    expected_size=1, expected_sha256="A" * 64,
                ):
                    raise RuntimeError(
                        "Creator recovery wrote through a link-like Mirror parent."
                    )
        finally:
            MIRROR_ROOT = saved_creator_mirror

    return "staging/SHA/hosts/report/unknown-static recovery + link policy"


def _self_test_embedded_assets() -> str:
    global DOWNLOADER_TEST_FILE, BRISQUE_FILE, MIRROR_ROOT

    saved_downloader_test = DOWNLOADER_TEST_FILE
    saved_brisque = BRISQUE_FILE
    saved_mirror_root = MIRROR_ROOT
    try:
        with tempfile.TemporaryDirectory(prefix="topaz-embedded-selftest-") as temp_name:
            root = Path(temp_name).resolve()
            MIRROR_ROOT = root
            DOWNLOADER_TEST_FILE = root / "_test" / "downloader-test.txt"
            BRISQUE_FILE = root / "v1" / "brisque.xml"

            ensure_known_embedded_support_assets()
            if DOWNLOADER_TEST_FILE.stat().st_size != DOWNLOADER_TEST_FALLBACK_SIZE:
                raise RuntimeError("downloader-test.txt embedded size failed.")
            if _self_test_sha256(DOWNLOADER_TEST_FILE) != DOWNLOADER_TEST_FALLBACK_SHA256:
                raise RuntimeError("downloader-test.txt embedded SHA-256 failed.")
            if BRISQUE_FILE.stat().st_size != BRISQUE_FALLBACK_SIZE:
                raise RuntimeError("brisque.xml embedded size failed.")
            if _self_test_sha256(BRISQUE_FILE) != BRISQUE_FALLBACK_SHA256:
                raise RuntimeError("brisque.xml embedded SHA-256 failed.")

            # Corrupt both and prove local reconstruction repairs them without network.
            DOWNLOADER_TEST_FILE.write_bytes(b"bad")
            BRISQUE_FILE.write_bytes(b"bad")
            ensure_known_embedded_support_assets()
            if _self_test_sha256(DOWNLOADER_TEST_FILE) != DOWNLOADER_TEST_FALLBACK_SHA256:
                raise RuntimeError("downloader-test.txt local repair failed.")
            if _self_test_sha256(BRISQUE_FILE) != BRISQUE_FALLBACK_SHA256:
                raise RuntimeError("brisque.xml local repair failed.")
    finally:
        DOWNLOADER_TEST_FILE = saved_downloader_test
        BRISQUE_FILE = saved_brisque
        MIRROR_ROOT = saved_mirror_root

    return "downloader-test.txt + brisque.xml exact offline reconstruction"


def _self_test_server_assets() -> str:
    global SERVER_ASSET_MANIFEST_FILE, MIRROR_ROOT, DISCOVERED_INVENTORY_FILE, DISCOVERED_ASSETS_FILE
    import runpy

    namespace = runpy.run_path(str(SERVER_PY))
    namespace["validate_server_assets"]()
    manifest = json.loads(SERVER_ASSET_MANIFEST_FILE.read_text(encoding="utf-8"))
    records = manifest.get("files", [])
    embedded_records = [
        item for item in records
        if isinstance(item, dict) and item.get("source") == "embedded_support"
    ]
    if len(embedded_records) != 24:
        raise RuntimeError(
            f"Expected 24 embedded Server Assets, found {len(embedded_records)}."
        )

    # Prove stale historical recovered_404 provenance cannot overwrite a
    # destination that is now part of the current embedded baseline.
    saved_manifest_file = SERVER_ASSET_MANIFEST_FILE
    try:
        with tempfile.TemporaryDirectory(prefix="topaz-server-assets-precedence-selftest-") as temp_name:
            SERVER_ASSET_MANIFEST_FILE = Path(temp_name) / "Server_Assets_Manifest.json"
            stale = server_asset_record(
                DOWNLOADER_TEST_FILE,
                source="recovered_404",
                source_url="https://models.topazlabs.com/_test/downloader-test.txt",
            )
            stale_records = [stale]
            stale_manifest = {
                "schema_version": 1,
                "creator_version": VERSION,
                "creator_build": BUILD,
                "mirror_relative_root": "Mirror",
                "hash_algorithm": "SHA256",
                "asset_count": len(stale_records),
                "records_payload_sha256": hashlib.sha256(
                    canonical_server_asset_payload(stale_records)
                ).hexdigest().upper(),
                "files": stale_records,
            }
            SERVER_ASSET_MANIFEST_FILE.write_text(
                json.dumps(stale_manifest, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            write_server_asset_manifest()
            migrated = json.loads(
                SERVER_ASSET_MANIFEST_FILE.read_text(encoding="utf-8")
            )
            downloader_relative = DOWNLOADER_TEST_FILE.relative_to(MIRROR_ROOT).as_posix()
            migrated_record = next(
                (
                    item for item in migrated.get("files", [])
                    if isinstance(item, dict)
                    and item.get("relative_path", "").casefold()
                    == downloader_relative.casefold()
                ),
                None,
            )
            if migrated_record is None or migrated_record.get("source") != "embedded_support":
                raise RuntimeError(
                    "Historical recovered Server Asset overrode embedded baseline provenance."
                )
    finally:
        SERVER_ASSET_MANIFEST_FILE = saved_manifest_file

    # Prove recovered provenance is pruned once the current V2 inventory owns
    # that destination, while the embedded Server Assets remain intact.
    saved_manifest_file = SERVER_ASSET_MANIFEST_FILE
    promoted_file = MIRROR_ROOT / "v1" / "v2-promotion-prune-selftest.bin"
    try:
        with tempfile.TemporaryDirectory(
            prefix="topaz-server-assets-v2-promotion-selftest-"
        ) as temp_name:
            SERVER_ASSET_MANIFEST_FILE = Path(temp_name) / "Server_Assets_Manifest.json"
            promoted_file.parent.mkdir(parents=True, exist_ok=True)
            promoted_file.write_bytes(b"v2-promotion-prune-selftest\n")
            stale = server_asset_record(
                promoted_file,
                source="recovered_404",
                source_url=(
                    "https://models.topazlabs.com/v1/"
                    "v2-promotion-prune-selftest.bin"
                ),
            )
            stale_records = [stale]
            stale_manifest = {
                "schema_version": 1,
                "creator_version": VERSION,
                "creator_build": BUILD,
                "mirror_relative_root": "Mirror",
                "hash_algorithm": "SHA256",
                "asset_count": len(stale_records),
                "records_payload_sha256": hashlib.sha256(
                    canonical_server_asset_payload(stale_records)
                ).hexdigest().upper(),
                "files": stale_records,
            }
            SERVER_ASSET_MANIFEST_FILE.write_text(
                json.dumps(stale_manifest, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            promoted_relative = promoted_file.relative_to(MIRROR_ROOT).as_posix()
            write_server_asset_manifest(
                v2_owned_keys={promoted_relative.casefold()}
            )
            migrated = json.loads(
                SERVER_ASSET_MANIFEST_FILE.read_text(encoding="utf-8")
            )
            if any(
                isinstance(item, dict)
                and str(item.get("relative_path", "")).casefold()
                == promoted_relative.casefold()
                for item in migrated.get("files", [])
            ):
                raise RuntimeError(
                    "V2-owned historical recovered Server Asset was not pruned."
                )
            if int(migrated.get("asset_count", -1)) != 24:
                raise RuntimeError(
                    "V2-promotion pruning changed the embedded Server Assets baseline."
                )
    finally:
        promoted_file.unlink(missing_ok=True)
        SERVER_ASSET_MANIFEST_FILE = saved_manifest_file

    # Prove corrupt dynamic provenance is rejected without touching the real manifest.
    saved_mirror_root = MIRROR_ROOT
    try:
        with tempfile.TemporaryDirectory(prefix="topaz-server-assets-selftest-") as temp_name:
            MIRROR_ROOT = Path(temp_name).resolve()
            dynamic_file = MIRROR_ROOT / "v1" / "future-selftest.xml"
            dynamic_file.parent.mkdir(parents=True)
            dynamic_file.write_bytes(b"<selftest/>\n")
            good = server_asset_record(
                dynamic_file,
                source="recovered_404",
                source_url="https://models.topazlabs.com/v1/future-selftest.xml",
            )
            if normalized_dynamic_server_asset_record(good) is None:
                raise RuntimeError("Valid dynamic Server Asset provenance was rejected.")
            bad_sha = dict(good)
            bad_sha["sha256"] = "0" * 64
            if normalized_dynamic_server_asset_record(bad_sha) is not None:
                raise RuntimeError("Corrupt dynamic Server Asset SHA provenance was trusted.")
            bad_url = dict(good)
            bad_url["source_url"] = "https://models.topazlabs.com/v1/other.xml"
            if normalized_dynamic_server_asset_record(bad_url) is not None:
                raise RuntimeError("Mismatched dynamic Server Asset URL provenance was trusted.")
    finally:
        MIRROR_ROOT = saved_mirror_root

    # Prove the two persistent discovery side manifests remain separate from
    # actionable schema-3 repair state and classify accepted extensions correctly.
    saved_discovered_inventory = DISCOVERED_INVENTORY_FILE
    saved_discovered_assets = DISCOVERED_ASSETS_FILE
    saved_discovery_server_manifest = SERVER_ASSET_MANIFEST_FILE
    discovery_test_root = MIRROR_ROOT / "_selftest_discovered"
    shutil.rmtree(discovery_test_root, ignore_errors=True)
    try:
        with tempfile.TemporaryDirectory(
            prefix="topaz-discovered-side-manifests-selftest-"
        ) as temp_name:
            temp_root = Path(temp_name).resolve()
            DISCOVERED_INVENTORY_FILE = (
                temp_root / "Manifests" / "Topaz_Offline_Download_Creator_Discovered_Inventory.v2.json"
            )
            DISCOVERED_ASSETS_FILE = (
                temp_root / "Manifests" / "Topaz_Offline_Download_Creator_Discovered_Assets.v2.json"
            )
            SERVER_ASSET_MANIFEST_FILE = (
                temp_root / "Manifests" / "Topaz_Offline_Download_Creator_Server_Assets_Manifest.json"
            )
            inventory_file = discovery_test_root / "future-model-selftest.tz3"
            asset_file = discovery_test_root / "future-support-selftest.svg"
            inventory_file.parent.mkdir(parents=True, exist_ok=True)
            asset_file.parent.mkdir(parents=True, exist_ok=True)
            inventory_file.write_bytes(b"future-model-selftest\n")
            asset_file.write_bytes(b"<svg>future-support-selftest</svg>\n")
            inventory_url = "https://video-models.topazlabs.com/_selftest_discovered/future-model-selftest.tz3"
            asset_url = "https://downloads.topazlabs.com/_selftest_discovered/future-support-selftest.svg"

            record_discovered_inventory(inventory_url, inventory_file)
            record_discovered_asset(asset_url, asset_file)

            inventory_payload = json.loads(DISCOVERED_INVENTORY_FILE.read_text(encoding="utf-8"))
            asset_payload = json.loads(DISCOVERED_ASSETS_FILE.read_text(encoding="utf-8"))
            if (
                inventory_payload.get("schema") != DISCOVERED_INVENTORY_SCHEMA
                or inventory_payload.get("schema_version") != DISCOVERED_SCHEMA_VERSION
                or inventory_payload.get("logical_entries") != 1
                or inventory_payload.get("unique_physical_files") != 1
            ):
                raise RuntimeError("Discovered inventory side-manifest framing failed.")
            if (
                asset_payload.get("schema") != DISCOVERED_ASSETS_SCHEMA
                or asset_payload.get("schema_version") != DISCOVERED_SCHEMA_VERSION
                or asset_payload.get("asset_count") != 1
            ):
                raise RuntimeError("Discovered assets side-manifest framing failed.")
            if len(load_discovered_inventory_records()) != 1:
                raise RuntimeError("Discovered inventory record count failed.")
            if len(load_discovered_asset_records()) != 1:
                raise RuntimeError("Discovered asset record count failed.")

            alias_url = (
                "https://models-r2.topazlabs.com/"
                "_selftest_discovered/future-model-selftest.tz3"
            )
            record_discovered_inventory(alias_url, inventory_file)
            alias_payload = json.loads(
                DISCOVERED_INVENTORY_FILE.read_text(encoding="utf-8")
            )
            if (
                alias_payload.get("logical_entries") != 2
                or alias_payload.get("unique_physical_files") != 1
            ):
                raise RuntimeError(
                    "Discovered inventory did not separate logical aliases from physical files."
                )

            # Prove legacy recovered Server Assets migrate into the correct
            # side manifest, then leave only support assets in runtime Server Assets.
            DISCOVERED_INVENTORY_FILE.unlink(missing_ok=True)
            DISCOVERED_ASSETS_FILE.unlink(missing_ok=True)
            legacy_records = [
                server_asset_record(
                    inventory_file, source="recovered_404", source_url=inventory_url
                ),
                server_asset_record(
                    asset_file, source="recovered_404", source_url=asset_url
                ),
            ]
            legacy_payload = canonical_server_asset_payload(legacy_records)
            SERVER_ASSET_MANIFEST_FILE.parent.mkdir(parents=True, exist_ok=True)
            SERVER_ASSET_MANIFEST_FILE.write_text(
                json.dumps({
                    "schema_version": 1,
                    "creator_version": VERSION,
                    "creator_build": BUILD,
                    "mirror_relative_root": "Mirror",
                    "hash_algorithm": "SHA256",
                    "asset_count": len(legacy_records),
                    "records_payload_sha256": hashlib.sha256(legacy_payload).hexdigest().upper(),
                    "files": legacy_records,
                }, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            sync_recovered_assets_report_from_server_assets(set())
            if len(load_discovered_inventory_records()) != 1:
                raise RuntimeError("Recovered model/package did not migrate to discovered inventory.")
            if len(load_discovered_asset_records()) != 1:
                raise RuntimeError("Recovered support file did not migrate to discovered assets.")
            write_server_asset_manifest(v2_owned_keys=set())
            rebuilt_server = json.loads(
                SERVER_ASSET_MANIFEST_FILE.read_text(encoding="utf-8")
            )
            rebuilt_paths = {
                str(item.get("relative_path", "")).casefold(): item.get("source")
                for item in rebuilt_server.get("files", [])
                if isinstance(item, dict)
            }
            inventory_relative = inventory_file.relative_to(MIRROR_ROOT).as_posix().casefold()
            asset_relative = asset_file.relative_to(MIRROR_ROOT).as_posix().casefold()
            if inventory_relative in rebuilt_paths:
                raise RuntimeError("Discovered inventory remained double-owned by Server Assets.")
            if rebuilt_paths.get(asset_relative) != "recovered_404":
                raise RuntimeError("Discovered support asset was lost from runtime Server Assets.")

            # An accepted inventory extension must not be accepted by the asset manifest.
            try:
                write_discovered_manifest(
                    [server_asset_record(inventory_file, source="recovered_404", source_url=inventory_url)],
                    inventory=False,
                )
            except RuntimeError:
                pass
            else:
                raise RuntimeError("Accepted inventory extension was misclassified as an asset.")

            actionable_repair = (
                temp_root / "Manifests" / "Topaz_Offline_Download_Creator_SHA256_Repair.json"
            )
            repair_failure = {
                "relative_path": "v1/actionable-repair-selftest.bin",
                "reason": "hash_mismatch",
                "expected_size": 64,
                "expected_sha256": "A" * 64,
                "actual": "B" * 64,
            }
            repair_failures = [repair_failure]
            repair_failures_bytes = json.dumps(
                repair_failures,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
            repair_payload = {
                "schema_version": 3,
                "creator_build": BUILD,
                "generated_utc": datetime.now().astimezone().isoformat(timespec="seconds"),
                "physical_records_payload_sha256": V2_PHYSICAL_RECORDS_PAYLOAD_SHA256,
                "failures_payload_sha256": hashlib.sha256(repair_failures_bytes).hexdigest().upper(),
                "failures": repair_failures,
            }
            actionable_repair.write_text(
                json.dumps(repair_payload, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            actionable_before = actionable_repair.read_bytes()
            # Rewriting either side manifest must never touch actionable repair state.
            write_discovered_manifest(load_discovered_inventory_records(), inventory=True)
            write_discovered_manifest(load_discovered_asset_records(), inventory=False)
            if actionable_repair.read_bytes() != actionable_before:
                raise RuntimeError("Discovery side-manifest write modified actionable repair state.")
            downloader_for_coexistence = runpy.run_path(str(OUT_PORTABLE_DOWNLOADER))
            downloader_for_coexistence["load_repair_paths"].__globals__["REPAIR_PATH"] = actionable_repair
            if len(downloader_for_coexistence["load_repair_paths"]()) != 1:
                raise RuntimeError("Generated Downloader rejected coexisting schema-3 repair state.")

            # Simulate a future frozen-manifest promotion. A stale side record for
            # an already base-owned path must be removed instead of double-counted.
            base_logical = next(
                item
                for item in current_logical_inventory_records()
                if PurePosixPath(str(item["relative_path"])).suffix.casefold()
                in DISCOVERED_INVENTORY_SUFFIXES
            )
            base_physical = next(
                item
                for item in validated_v2_physical_records()
                if str(item["relative_path"]).casefold()
                == str(base_logical["relative_path"]).casefold()
            )
            promoted_record = {
                "relative_path": str(base_logical["relative_path"]),
                "size_bytes": int(base_physical["size_bytes"]),
                "sha256": str(base_physical["sha256"]).upper(),
                "source": "recovered_404",
                "source_url": str(base_logical["url"]),
            }
            promoted_records = [promoted_record]
            promoted_bytes = canonical_discovered_payload(promoted_records)
            DISCOVERED_INVENTORY_FILE.write_text(
                json.dumps({
                    "schema": DISCOVERED_INVENTORY_SCHEMA,
                    "schema_version": DISCOVERED_SCHEMA_VERSION,
                    "creator_version": VERSION,
                    "creator_build": BUILD,
                    "generated_utc": datetime.now().astimezone().isoformat(timespec="seconds"),
                    "mirror_relative_root": "Mirror",
                    "hash_algorithm": "SHA256",
                    "logical_entries": 1,
                    "unique_physical_files": 1,
                    "accepted_extensions": sorted(DISCOVERED_INVENTORY_SUFFIXES),
                    "records_payload_sha256": hashlib.sha256(promoted_bytes).hexdigest().upper(),
                    "files": promoted_records,
                }, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            if prune_discovered_inventory_promoted_to_base() != 1:
                raise RuntimeError("Promoted discovered inventory was not pruned.")
            if DISCOVERED_INVENTORY_FILE.exists():
                raise RuntimeError("Empty promoted discovered inventory side manifest remained.")
    finally:
        shutil.rmtree(discovery_test_root, ignore_errors=True)
        DISCOVERED_INVENTORY_FILE = saved_discovered_inventory
        DISCOVERED_ASSETS_FILE = saved_discovered_assets
        SERVER_ASSET_MANIFEST_FILE = saved_discovery_server_manifest

    return (
        f"24 embedded baseline; manifest count {len(records)}; stale dynamic precedence + "
        "V2 promotion pruned; corrupt provenance rejected; discovery migration/promotion + repair coexistence passed"
    )


def _self_test_generated_programs() -> str:
    import contextlib
    import io
    from http import HTTPStatus

    generated = (
        OUT_PORTABLE_DOWNLOADER,
        OUT_PORTABLE_SHA256_VERIFIER,
        SERVER_PY,
    )
    for path in generated:
        try:
            source_bytes = path.read_bytes()
        except OSError as exc:
            raise RuntimeError(
                f"Unable to read generated program: {path.name}: {exc}"
            ) from exc
        if b"\x1B" in source_bytes:
            raise RuntimeError(
                f"Generated program contains a literal ESC control byte: {path.name}."
            )
        try:
            compile(source_bytes, str(path), "exec")
        except SyntaxError as exc:
            raise RuntimeError(
                f"Generated program compile failed: {path.name}: {exc}"
            ) from exc

    for path in (OUT_PORTABLE_DOWNLOADER, OUT_PORTABLE_SHA256_VERIFIER):
        validation = subprocess.run(
            [sys.executable, str(path), "--validate-only"],
            capture_output=True,
            text=True,
            check=False,
        )
        if validation.returncode != 0:
            raise RuntimeError(
                f"Generated validate-only failed: {path.name}: "
                + (validation.stderr.strip() or validation.stdout.strip())
            )

    downloader_fatal = subprocess.run(
        [sys.executable, str(OUT_PORTABLE_DOWNLOADER), "--invalid-self-test-option"],
        capture_output=True,
        text=True,
        check=False,
    )
    if downloader_fatal.returncode != 2:
        raise RuntimeError(
            "Generated Downloader fatal/configuration errors must exit 2; "
            f"received {downloader_fatal.returncode}."
        )

    verifier_source = OUT_PORTABLE_SHA256_VERIFIER.read_text(encoding="utf-8")
    required_verifier_markers = (
        'load_discovered_inventory_records(',
        '+ discovered_logical_count',
        'File SHA and Download Validation',
        'VALIDATION_LABEL_WIDTH = len("File/Content Integrity Result")',
        'return f"{label:<{VALIDATION_LABEL_WIDTH}}: {value}"',
        'validation_line("Verifying File Set", f"0 / {logical_record_count}")',
        '"Verified File Set",',
        'result["sha256_validated"] = sha256_validated_logical_entries',
        'result["sha256_expected"] = sum(',
        '"Inventory SHA-256 Verified"',
        '"Server Asset SHA-256 Verified"',
        'server_sha_validated != server_sha_expected',
        'write_repair_list(index, result["failures"])',
        'any(',
        'failure.get("reason") in {"hash_mismatch", "read_error"}',
        'validation_line("SHA-256 Integrity Result",',
        'validation_line("File/Content Integrity Result",',
        'DISCOVERED_INVENTORY_PATH',
        'DISCOVERED_ASSETS_PATH',
        'validation_line("Discovered Inventory Entries", discovered_inventory_entries)',
        'validation_line("Discovered Asset Files", discovered_assets)',
        '"~Discovered_Inventory.v2.json",',
        '"~Discovered_Assets.v2.json",',
        'print("Report File(s) to Script Creator")',
        'mirror_path_has_link_component',
        'processed_logical_entries != logical_record_count',
        'with zipfile.ZipFile(path) as archive:',
        'bad_member = archive.testzip()',
        'import zlib',
        'import lzma',
        'zipfile.BadZipFile, zlib.error',
        'lzma.LZMAError',
    )
    for marker in required_verifier_markers:
        if marker not in verifier_source:
            raise RuntimeError(
                "Generated verifier is missing complete-inventory counter behavior: " + marker
            )
    removed_v2_success_marker = (
        'SHA-256 verification passed for all ' + 'V2-backed records.'
    )
    forbidden_verifier_markers = (
        'OVERALL_LOGICAL_INVENTORY_ENTRIES',
        '/ {v2_logical_record_count}',
        'V2-verified',
        removed_v2_success_marker,
        'repair_path_is_script_creator_report',
        'validation_line("Found Repair Report", "~SHA256_Repair.json")',
    )
    for marker in forbidden_verifier_markers:
        if marker in verifier_source:
            raise RuntimeError(
                "Generated verifier exposes a V2-only inventory denominator: " + marker
            )
    if verifier_source.count('print()\n\n    for record in supplemental_records:'):
        raise RuntimeError(
            "Generated verifier splits the SHA-256 progress counter before supplemental records."
        )

    downloader_source = OUT_PORTABLE_DOWNLOADER.read_text(encoding="utf-8")
    for marker in (
        'verify_zip_crc: bool = False',
        'with zipfile.ZipFile(path) as archive:',
        'valid = archive.testzip() is None',
        'verify_zip_crc=verify_zip_crc',
        'if content_suffix == ".part":',
        'import zlib',
        'import lzma',
        'zipfile.BadZipFile, zlib.error',
        'lzma.LZMAError',
        'raise SystemExit(2)',
        'download_report_url_is_unresolved',
        'authoritative_sha = str(item.get("sha256", "") or "").upper()',
        'allowed_protocol = "=http,https" if parsed_url.scheme.lower() == "http" else "=https"',
        'report_failed_download(url)',
        'settings.get("partial_sha256", "")',
        '"partial_has_prior_bytes": partial.is_file()',
        'partial_sha256=authoritative_sha',
        'physical: dict[str, tuple[str, int, bool]]',
        'verify_zip_crc = previous[2] or verify_zip_crc',
        'def _process_download_groups(',
        'def _process_repair_groups(',
        'process_repair_group(',
        '--repair-only',
        '--repair-network-check',
        'def _validated_repair_failures(payload: dict) -> list[dict]:',
        'if not repair_paths:',
        'return 3',
        'def repair_downloads_available()',
        'all_groups_valid = True',
        'for group in runtime_groups():',
        'load_discovered_inventory_group',
        'path_is_link_like',
        'success = groups_valid and reported_zip_valid and not final_failures',
        'def validate_zip_content(',
        'announce: bool = False',
        'Validating ZIP content: {path.name}',
        'ZIP content validation {status}: {path.name}',
        'def process_reported_unhashed_zip_validation(',
        'downloads_enabled: bool',
        'section("Reported ZIP Content Validation")',
        'reported_zip_valid = process_reported_unhashed_zip_validation(',
        'Attempting a validated replacement download.',
        'Reported ZIP replacement downloaded and validated, but ',
        'download_report_url_is_unresolved(url)',
        'verify_zip_crc=True',
        'settings.get("close_report_on_success", True)',
        'close_report_on_success=False',
        'def split_download_report_records(text: str) -> list[str]:',
        'any(not character.isprintable() for character in url)',
        'report_failed_download(FAVICON_URL)',
        'if not mark_download_report_fixed(FAVICON_URL):',
        'report_state_incomplete = False',
        "FAILED integrity/content validation: {state['destination'].name}",
        'def group_file_is_valid(',
        'validation_cache: dict[str, tuple[tuple[int, int], bool]]',
        'file_validation_signature(path)',
    ):
        if marker not in downloader_source:
            raise RuntimeError(
                "Generated Downloader is missing supplemental ZIP CRC validation: " + marker
            )

    forbidden_downloader_markers = (
        'return all(\n        process_group(group, backend, downloads_enabled, repair_paths)',
        'DISCOVERED_ASSETS_SCHEMA',
        '_payload_is_script_creator_report',
        '_validate_script_creator_report_payload',
    )
